#[doc = "Original `SoloFeature::countVelocyto` at STAR/source/SoloFeature_countVelocyto.cpp:12. Args: "]
pub fn solofeature_countvelocyto_l12_solofeature_countvelocyto(
    solo_feature: &mut crate::generated::structs::SoloFeature,
    gene_feature_read_info: &[crate::generated::structs::SoloFeatureReadInfo],
    transcriptome: &crate::generated::structs::Transcriptome,
    run_thread_n: i32,
    time_allocated: &str,
    time_finished_input: &str,
    time_finished_collapsing: &str,
    linux_proc_memory: &str,
) -> String {
    use std::collections::{BTreeMap, HashMap};
    use std::fmt::Write;

    solo_feature
        .n_read_per_cb
        .resize(solo_feature.n_cb as usize, 0);

    let read_feat_sum = solo_feature
        .read_feat_sum
        .as_mut()
        .expect("SoloFeature::countVelocyto requires readFeatSum");

    let mut cu_tr_types: Vec<HashMap<u64, Vec<crate::generated::structs::TrTypeStruct>>> =
        Vec::with_capacity(solo_feature.n_cb as usize);
    for ii in 0..solo_feature.n_cb as usize {
        let cap = if read_feat_sum.cb_read_count[ii] > 100 {
            read_feat_sum.cb_read_count[ii]
        } else {
            read_feat_sum.cb_read_count[ii] / 5
        };
        cu_tr_types.push(HashMap::with_capacity(cap as usize));
    }

    let mut log_main = String::new();
    writeln!(
        log_main,
        "{} ... Velocyto counting: allocated arrays",
        time_allocated
    )
    .unwrap();

    for i_thread in 0..run_thread_n as usize {
        let Some(read_feat) = solo_feature.read_feat_all.get(i_thread) else {
            continue;
        };
        let mut tokens = read_feat.stream_reads.split_whitespace();
        while let Some(iread_token) = tokens.next() {
            let iread = iread_token.parse::<usize>().unwrap();
            let cb = gene_feature_read_info[iread].cb;
            let umi = gene_feature_read_info[iread].umi;
            if cb == -1 || umi == u64::MAX {
                let n_tr = tokens
                    .next()
                    .and_then(|x| x.parse::<usize>().ok())
                    .unwrap_or(0);
                for _ in 0..2 * n_tr {
                    let _ = tokens.next();
                }
                continue;
            }

            let i_cb = solo_feature.ind_cb_wl[cb as usize] as usize;
            solo_feature.n_read_per_cb[i_cb] += 1;

            if cu_tr_types[i_cb].get(&umi).is_some_and(|v| v.is_empty()) {
                let n_tr = tokens
                    .next()
                    .and_then(|x| x.parse::<usize>().ok())
                    .unwrap_or(0);
                for _ in 0..2 * n_tr {
                    let _ = tokens.next();
                }
                continue;
            }

            let n_tr = tokens.next().unwrap().parse::<usize>().unwrap();
            let mut tr_t = Vec::with_capacity(n_tr);
            for _ in 0..n_tr {
                let tr = tokens.next().unwrap().parse::<u32>().unwrap();
                let type_ = tokens.next().unwrap().parse::<u32>().unwrap() as u8;
                tr_t.push(crate::generated::structs::TrTypeStruct { tr, type_ });
            }

            if !cu_tr_types[i_cb].contains_key(&umi) {
                cu_tr_types[i_cb].insert(umi, tr_t);
                continue;
            }

            let old = cu_tr_types[i_cb].get(&umi).cloned().unwrap();
            let mut inew = 0usize;
            let mut tr_t1 = Vec::with_capacity(old.len());
            for old_tt in old {
                while inew < tr_t.len() && old_tt.tr > tr_t[inew].tr {
                    inew += 1;
                }
                if inew == tr_t.len() {
                    break;
                }
                if old_tt.tr == tr_t[inew].tr {
                    tr_t1.push(crate::generated::structs::TrTypeStruct {
                        tr: tr_t[inew].tr,
                        type_: old_tt.type_ | tr_t[inew].type_,
                    });
                }
            }
            cu_tr_types[i_cb].insert(umi, tr_t1);
        }
    }

    writeln!(
        log_main,
        "{} ... Velocyto counting: finished input",
        time_finished_input
    )
    .unwrap();

    solo_feature
        .n_umi_per_cb
        .resize(solo_feature.n_cb as usize, 0);
    solo_feature
        .n_gene_per_cb
        .resize(solo_feature.n_cb as usize, 0);
    solo_feature.count_mat_stride = 4;
    solo_feature.count_cell_gene_umi.resize(
        solo_feature.n_reads_mapped as usize * solo_feature.count_mat_stride as usize / 5 + 16,
        0,
    );
    solo_feature
        .count_cell_gene_umi_index
        .resize(solo_feature.n_cb as usize + 1, 0);
    solo_feature.count_cell_gene_umi_index[0] = 0;

    for (i_cb, umi_map) in cu_tr_types
        .iter()
        .enumerate()
        .take(solo_feature.n_cb as usize)
    {
        let mut gene_c: BTreeMap<u32, [u32; 3]> = BTreeMap::new();
        for tr_types in umi_map.values() {
            if tr_types.is_empty() {
                continue;
            }
            let mut gene_i = transcriptome.tr_gene[tr_types[0].tr as usize];
            let mut exon_model = false;
            let mut intron_model = false;
            let mut span_model = true;
            let mut mixed_model = false;

            for tt in tr_types {
                if transcriptome.tr_gene[tt.tr as usize] != gene_i {
                    gene_i = u32::MAX;
                    break;
                }
                let has_intron = (tt.type_ & (1_u8 << ALIGN_VS_TRANSCRIPT_INTRON as u32)) != 0;
                let has_exon_intron =
                    (tt.type_ & (1_u8 << ALIGN_VS_TRANSCRIPT_EXON_INTRON as u32)) != 0;
                let has_span =
                    (tt.type_ & (1_u8 << ALIGN_VS_TRANSCRIPT_EXON_INTRON_SPAN as u32)) != 0;
                let has_concordant =
                    (tt.type_ & (1_u8 << ALIGN_VS_TRANSCRIPT_CONCORDANT as u32)) != 0;

                mixed_model |= ((has_intron && has_concordant) || has_exon_intron) && !has_span;
                span_model &= has_span;
                exon_model |= has_concordant && !has_intron && !has_exon_intron;
                intron_model |= has_intron && !has_exon_intron && !has_concordant;
            }

            if gene_i == u32::MAX {
                continue;
            }

            let counts = gene_c.entry(gene_i).or_insert([0; 3]);
            if exon_model && !intron_model && !mixed_model {
                counts[0] += 1;
            } else if span_model || ((intron_model || mixed_model) && !exon_model) {
                counts[1] += 1;
            } else {
                counts[2] += 1;
            }
            solo_feature.n_umi_per_cb[i_cb] += 1;
        }

        solo_feature.count_cell_gene_umi_index[i_cb + 1] =
            solo_feature.count_cell_gene_umi_index[i_cb];
        if solo_feature.n_umi_per_cb[i_cb] == 0 {
            continue;
        }

        solo_feature.n_gene_per_cb[i_cb] += gene_c.len() as u32;
        read_feat_sum.stats.v[SOLO_READ_FEATURE_STAT_YES_UMIS] +=
            solo_feature.n_umi_per_cb[i_cb] as u64;
        read_feat_sum.stats.v[SOLO_READ_FEATURE_STAT_YES_CELL_BARCODES] += 1;

        let needed = solo_feature.count_cell_gene_umi_index[i_cb + 1] as usize
            + gene_c.len() * solo_feature.count_mat_stride as usize;
        if solo_feature.count_cell_gene_umi.len() < needed {
            let new_len = (solo_feature.count_cell_gene_umi.len() * 2).max(needed);
            solo_feature.count_cell_gene_umi.resize(new_len, 0);
        }

        for (gene, counts) in gene_c {
            let idx = solo_feature.count_cell_gene_umi_index[i_cb + 1] as usize;
            solo_feature.count_cell_gene_umi[idx] = gene;
            for ii in 0..3 {
                solo_feature.count_cell_gene_umi[idx + 1 + ii] = counts[ii];
            }
            solo_feature.count_cell_gene_umi_index[i_cb + 1] += solo_feature.count_mat_stride;
        }
    }

    solo_feature.n_read_per_cb_total = solo_feature.n_read_per_cb.clone();
    solo_feature.n_read_per_cb_unique = solo_feature.n_read_per_cb.clone();

    writeln!(
        log_main,
        "{} ... Velocyto counting: finished collapsing UMIs",
        time_finished_collapsing
    )
    .unwrap();
    write!(
        log_main,
        "RAM for solo feature Velocyto\n{}",
        linux_proc_memory
    )
    .unwrap();
    log_main
}

#[doc = "Original `sjdbBuildIndex` at STAR/source/sjdbBuildIndex.cpp:16. Args: P: Parameters, Gsj: char, G: char, SA: PackedArray, SA2: PackedArray, SAi: PackedArray, mapGen: Genome, mapGen1: Genome"]
pub fn sjdbbuildindex_l16_sjdbbuildindex(
    _p: &crate::generated::structs::Parameters,
    gsj: &mut Vec<u8>,
    g: &mut Vec<u8>,
    sa: &mut crate::generated::structs::PackedArray,
    sa2: &mut crate::generated::structs::PackedArray,
    sai: &mut crate::generated::structs::PackedArray,
    map_gen: &mut crate::generated::structs::Genome,
    map_gen1: &crate::generated::structs::Genome,
) -> Result<crate::generated::structs::SjdbBuildIndexResult, String> {
    let mut result = crate::generated::structs::SjdbBuildIndexResult::default();
    if map_gen.sjdb_n == 0 {
        return Ok(result);
    }

    result.log_main.push_str(&format!(
        "{} ..... inserting junctions into the genome indices\n",
        timefunctions_l4_timemonthdaytime()
    ));

    let n_gsj = map_gen.sjdb_length * map_gen.sjdb_n;
    result.n_gsj = n_gsj;
    let needed = n_gsj as usize * 2 + 1;
    if gsj.len() < needed {
        gsj.resize(needed, GENOME_SPACING_CHAR);
    }
    for ii in 1..=map_gen.sjdb_n as usize {
        gsj[ii * map_gen.sjdb_length as usize - 1] = GENOME_SPACING_CHAR;
    }
    gsj[n_gsj as usize * 2] = GENOME_SPACING_CHAR;

    for ii in 0..n_gsj as usize {
        let value = gsj[ii];
        gsj[n_gsj as usize * 2 - 1 - ii] = if value < 4 { 3 - value } else { value };
    }

    let mut g1c = vec![0_u8; n_gsj as usize * 2 + 1];
    sequencefuns_l4_complementseqnumbers(gsj, &mut g1c, n_gsj * 2 + 1);

    if map_gen.sa.is_empty() && sa.length > 0 && !sa.char_array.is_empty() {
        map_gen.sa = (0..sa.length)
            .map(|ii| packedarray_h18_packedarray_index(sa, ii) as u32)
            .collect();
    }

    let mut old_sj_ind = vec![0_u32; map_gen1.sjdb_n as usize];
    let n_indices_sj1 = map_gen.sjdb_length;
    let mut ind_array: Vec<[u64; 2]> = Vec::new();
    let mut sj_new = 0_u64;

    for isj in 0..2 * map_gen.sjdb_n {
        let isj_usize = isj as usize;
        let seq0 = &gsj[..];
        let seq1 = &g1c[..];
        let isj1 = if isj < map_gen.sjdb_n {
            isj
        } else {
            2 * map_gen.sjdb_n - 1 - isj
        };
        let sjdb_ind = if map_gen1.sjdb_n == 0 {
            -1
        } else {
            binarysearch2_l3_binarysearch2(
                map_gen.sjdb_start[isj1 as usize],
                map_gen.sjdb_end[isj1 as usize],
                &map_gen1.sjdb_start,
                &map_gen1.sjdb_end,
                map_gen1.sjdb_n as i32,
            )
        };
        if sjdb_ind < 0 {
            sj_new += 1;
        } else if (sjdb_ind as usize) < old_sj_ind.len() {
            old_sj_ind[sjdb_ind as usize] = isj1;
        }

        for istart1 in 0..n_indices_sj1 {
            let istart = istart1;
            let seq_offset = isj * map_gen.sjdb_length + istart;
            if sjdb_ind >= 0 || gsj[seq_offset as usize] > 3 {
                continue;
            }
            let mut l = 0_u32;
            let sa_index = suffixarrayfuns_l297_suffixarraysearch1(
                map_gen,
                [seq0, seq1],
                seq_offset,
                10000,
                u64::MAX,
                true,
                0,
                map_gen.n_sa.saturating_sub(1),
                &mut l,
            );
            ind_array.push([
                sa_index,
                (isj_usize as u64) * map_gen.sjdb_length as u64 + istart as u64,
            ]);
        }
    }
    sj_new /= 2;
    result.sj_new = sj_new;
    result.log_main.push_str(&format!(
        "{}   Finished SA search: number of new junctions={}, old junctions={}\n",
        timefunctions_l4_timemonthdaytime(),
        sj_new,
        map_gen.sjdb_n as u64 - sj_new
    ));

    ind_array.sort_by(|a, b| {
        let cmp = funcompareuintandsuffixes_l6_funcompareuintandsuffixes(a, b, gsj);
        cmp.cmp(&0)
    });
    let n_ind = ind_array.len() as u32;
    result.n_ind = n_ind;
    result.ind_array = ind_array.clone();
    result.log_main.push_str(&format!(
        "{}   Finished sorting SA indicesL nInd={}\n",
        timefunctions_l4_timemonthdaytime(),
        n_ind
    ));

    map_gen.n_genome = map_gen.chr_start[map_gen.n_chr_real as usize] + n_gsj as u64;
    map_gen.n_sa += n_ind;

    let mut gstrand_bit1 = ((map_gen.n_genome as f64).ln() / 2.0_f64.ln()).floor() as u32 + 1;
    if gstrand_bit1 < 32 {
        gstrand_bit1 = 32;
    }
    result.log_main.push_str(&format!(
        "Genome size with junctions={}  {}   {}\n",
        map_gen.n_genome, map_gen.chr_start[map_gen.n_chr_real as usize], n_gsj
    ));
    result.log_main.push_str(&format!(
        "GstrandBit1={}   GstrandBit={}\n",
        gstrand_bit1, map_gen.gstrand_bit
    ));
    if gstrand_bit1 > map_gen.gstrand_bit {
        return Err("EXITING because of FATAL ERROR: cannot insert junctions on the fly because of strand GstrandBit problem\nSOLUTION: please contact STAR author at https://groups.google.com/forum/#!forum/rna-star\n".to_string());
    }

    packedarray_l8_packedarray_definebits(sa2, map_gen.gstrand_bit as u64 + 1, map_gen.n_sa as u64);
    packedarray_l31_packedarray_allocatearray(sa2);

    let n_gsj_new = sj_new * map_gen.sjdb_length as u64;
    let n2bit = 1_u64 << map_gen.gstrand_bit;
    let strand_mask = !n2bit;

    let mut isj = 0_usize;
    let mut isa2 = 0_u64;
    for isa in 0..map_gen1.n_sa as u64 {
        while isj < ind_array.len() && isa == ind_array[isj][0] {
            let mut ind1 = ind_array[isj][1];
            if ind1 < n_gsj as u64 {
                ind1 += map_gen.chr_start[map_gen.n_chr_real as usize];
            } else {
                ind1 = (ind1 - n_gsj as u64) | n2bit;
            }
            packedarray_l17_packedarray_writepacked(sa2, isa2, ind1);
            isa2 += 1;
            isj += 1;
        }

        let mut ind1 = packedarray_h18_packedarray_index(sa, isa);
        if (ind1 & n2bit) > 0 {
            let mut ind1s = map_gen1.n_genome - (ind1 & strand_mask);
            if ind1s >= map_gen.chr_start[map_gen.n_chr_real as usize] {
                let sj1 = ((ind1s - map_gen.chr_start[map_gen.n_chr_real as usize])
                    / map_gen.sjdb_length as u64) as usize;
                let old = old_sj_ind.get(sj1).copied().unwrap_or(sj1 as u32) as i64 - sj1 as i64;
                ind1s = (ind1s as i64 + old * map_gen.sjdb_length as i64) as u64;
                ind1 = (map_gen.n_genome - ind1s) | n2bit;
            } else {
                ind1 += n_gsj_new;
            }
        } else if ind1 >= map_gen.chr_start[map_gen.n_chr_real as usize] {
            let sj1 = ((ind1 - map_gen.chr_start[map_gen.n_chr_real as usize])
                / map_gen.sjdb_length as u64) as usize;
            let old = old_sj_ind.get(sj1).copied().unwrap_or(sj1 as u32) as i64 - sj1 as i64;
            ind1 = (ind1 as i64 + old * map_gen.sjdb_length as i64) as u64;
        }
        packedarray_l17_packedarray_writepacked(sa2, isa2, ind1);
        isa2 += 1;
    }

    while isj < ind_array.len() {
        let mut ind1 = ind_array[isj][1];
        if ind1 < n_gsj as u64 {
            ind1 += map_gen.chr_start[map_gen.n_chr_real as usize];
        } else {
            ind1 = (ind1 - n_gsj as u64) | n2bit;
        }
        packedarray_l17_packedarray_writepacked(sa2, isa2, ind1);
        isa2 += 1;
        isj += 1;
    }
    result.log_main.push_str(&format!(
        "{}   Finished inserting junction indices\n",
        timefunctions_l4_timemonthdaytime()
    ));

    if !sai.char_array.is_empty() && !map_gen.genome_sa_index_start.is_empty() {
        for i_l in 0..map_gen.p_ge.g_saindex_nbases {
            let mut i_sj = 0_usize;
            let start = map_gen.genome_sa_index_start[i_l as usize];
            let end = map_gen.genome_sa_index_start[i_l as usize + 1];
            let mut ind0 = start.saturating_sub(1);
            for ii in start..end {
                let i_sa1 = packedarray_h18_packedarray_index(sai, ii as u64);
                let i_sa2 = i_sa1
                    & map_gen.sai_mark_nmask as u64
                    & !(map_gen.sai_mark_absent_mask_c as u64);
                if i_sj < ind_array.len() && (i_sa1 & map_gen.sai_mark_absent_mask_c as u64) > 0 {
                    let i_sj1 = i_sj;
                    let mut ind1 = suffixarrayfuns_l397_funcalcsai(
                        &gsj[ind_array[2 * 0.min(ind_array.len())][1] as usize..],
                        0,
                    );
                    if i_sj < ind_array.len() {
                        ind1 = suffixarrayfuns_l397_funcalcsai(
                            &gsj[ind_array[i_sj][1] as usize..],
                            i_l,
                        );
                    }
                    while i_sj < ind_array.len()
                        && ind1 < (ii - start) as i64
                        && ind_array[i_sj][0].saturating_sub(1) < i_sa2
                    {
                        i_sj += 1;
                        if i_sj < ind_array.len() {
                            ind1 = suffixarrayfuns_l397_funcalcsai(
                                &gsj[ind_array[i_sj][1] as usize..],
                                i_l,
                            );
                        }
                    }
                    if i_sj < ind_array.len() && ind1 == (ii - start) as i64 {
                        let value = ind_array[i_sj][0].saturating_sub(1) + i_sj as u64 + 1;
                        packedarray_l17_packedarray_writepacked(sai, ii as u64, value);
                        for ii0 in ind0 + 1..ii {
                            packedarray_l17_packedarray_writepacked(
                                sai,
                                ii0 as u64,
                                value | map_gen.sai_mark_absent_mask_c as u64,
                            );
                        }
                        i_sj += 1;
                        ind0 = ii;
                    } else {
                        i_sj = i_sj1;
                    }
                } else {
                    while i_sj < ind_array.len() && ind_array[i_sj][0].saturating_sub(1) + 1 < i_sa2
                    {
                        i_sj += 1;
                    }
                    while i_sj < ind_array.len()
                        && ind_array[i_sj][0].saturating_sub(1) + 1 == i_sa2
                    {
                        if suffixarrayfuns_l397_funcalcsai(&gsj[ind_array[i_sj][1] as usize..], i_l)
                            >= (ii - start) as i64
                        {
                            break;
                        }
                        i_sj += 1;
                    }
                    packedarray_l17_packedarray_writepacked(sai, ii as u64, i_sa1 + i_sj as u64);
                    for ii0 in ind0 + 1..ii {
                        packedarray_l17_packedarray_writepacked(
                            sai,
                            ii0 as u64,
                            (i_sa2 + i_sj as u64) | map_gen.sai_mark_absent_mask_c as u64,
                        );
                    }
                    ind0 = ii;
                }
            }
        }

        for pair in &ind_array {
            let mut ind1 = 0_i64;
            for i_l in 0..map_gen.p_ge.g_saindex_nbases {
                let gg = gsj[pair[1] as usize + i_l as usize] as u32;
                ind1 <<= 2;
                if gg > 3 {
                    for i_l1 in i_l..map_gen.p_ge.g_saindex_nbases {
                        ind1 += 3;
                        let mut ind2 = map_gen.genome_sa_index_start[i_l1 as usize] as i64 + ind1;
                        while ind2 >= 0 {
                            if (packedarray_h18_packedarray_index(sai, ind2 as u64)
                                & map_gen.sai_mark_absent_mask_c as u64)
                                == 0
                            {
                                break;
                            }
                            ind2 -= 1;
                        }
                        if ind2 >= 0 {
                            let old = packedarray_h18_packedarray_index(sai, ind2 as u64);
                            packedarray_l17_packedarray_writepacked(
                                sai,
                                ind2 as u64,
                                old | map_gen.sai_mark_nmask_c as u64,
                            );
                        }
                        ind1 <<= 2;
                    }
                    break;
                } else {
                    ind1 += gg as i64;
                }
            }
        }
    }
    result.log_main.push_str(&format!(
        "{}   Finished SAi\n",
        timefunctions_l4_timemonthdaytime()
    ));

    packedarray_l8_packedarray_definebits(sa, map_gen.gstrand_bit as u64 + 1, map_gen.n_sa as u64);
    packedarray_l27_packedarray_pointarray(sa, &sa2.char_array);
    map_gen.n_sa_byte = sa.length_byte as u32;
    map_gen.sj_gstart = map_gen.chr_start[map_gen.n_chr_real as usize];
    let g_start = map_gen.chr_start[map_gen.n_chr_real as usize] as usize;
    if g.len() < g_start + n_gsj as usize {
        g.resize(g_start + n_gsj as usize, GENOME_SPACING_CHAR);
    }
    g[g_start..g_start + n_gsj as usize].copy_from_slice(&gsj[..n_gsj as usize]);
    map_gen.g = g.clone();
    map_gen.sa = (0..sa.length)
        .map(|ii| packedarray_h18_packedarray_index(sa, ii) as u32)
        .collect();
    Ok(result)
}

#[doc = "Original `genomeSAindex` at STAR/source/genomeSAindex.cpp:6. Args: G: char, SA: PackedArray, P: Parameters, SAi: PackedArray, mapGen: Genome"]
pub fn genomesaindex_l6_genomesaindex(
    g: &[u8],
    sa: &[u64],
    map_gen: &mut crate::generated::structs::Genome,
) -> Result<Vec<u32>, String> {
    map_gen.genome_sa_index_start = vec![0; map_gen.p_ge.g_saindex_nbases as usize + 1];
    for ii in 1..=map_gen.p_ge.g_saindex_nbases as usize {
        map_gen.genome_sa_index_start[ii] =
            map_gen.genome_sa_index_start[ii - 1] + (1u32 << (2 * ii as u32));
    }
    let n_sai = map_gen.genome_sa_index_start[map_gen.p_ge.g_saindex_nbases as usize];

    map_gen.sai_mark_nmask_c = if map_gen.gstrand_bit + 1 >= 32 {
        0
    } else {
        1u32 << (map_gen.gstrand_bit + 1)
    };
    map_gen.sai_mark_nmask = !map_gen.sai_mark_nmask_c;
    map_gen.sai_mark_absent_mask_c = if map_gen.gstrand_bit + 2 >= 32 {
        0
    } else {
        1u32 << (map_gen.gstrand_bit + 2)
    };
    if map_gen.n_sa == 0 {
        map_gen.n_sa = sa.len() as u32;
    }

    let mut sai = vec![0u32; n_sai as usize];
    if !sa.is_empty() {
        genomesaindex_l117_genomesaindexchunk(g, sa, &mut sai, 0, sa.len() as u32 - 1, map_gen)?;
    }
    map_gen.sai = sai.clone();
    Ok(sai)
}

#[doc = "Original `genomeSAindexChunk` at STAR/source/genomeSAindex.cpp:117. Args: G: char, SA: PackedArray, P: Parameters, SAi: PackedArray, iSA1: uint, iSA2: uint, mapGen: Genome"]
pub fn genomesaindex_l117_genomesaindexchunk(
    g: &[u8],
    sa: &[u64],
    sai: &mut [u32],
    i_sa1: u32,
    i_sa2: u32,
    map_gen: &crate::generated::structs::Genome,
) -> Result<(), String> {
    let index_bases = map_gen.p_ge.g_saindex_nbases as usize;
    if index_bases == 0 {
        return Ok(());
    }
    if map_gen.n_sa == 0 {
        return Err("BUG: empty suffix array in genomeSAindexChunk\n".to_string());
    }

    let mut ind0 = vec![u32::MAX; index_bases];
    let isa_step = map_gen.n_sa as u64 / (1u64 << (2 * map_gen.p_ge.g_saindex_nbases)) + 1;
    let mut isa = i_sa1 as u64;
    let mut i_l4 = 0;
    let mut ind_full = suffixarrayfuns_l353_funcalcsaifromsa(
        g,
        sa,
        map_gen.n_genome,
        map_gen.gstrand_bit as u8,
        map_gen.gstrand_mask as u64,
        isa,
        map_gen.p_ge.g_saindex_nbases as i32,
        &mut i_l4,
    );

    while isa <= i_sa2 as u64 {
        for i_l in 0..index_bases {
            let shift = 2 * (map_gen.p_ge.g_saindex_nbases as usize - 1 - i_l);
            let ind_pref = (ind_full >> shift) as u32;

            if i_l as i32 == i_l4 {
                for i_l1 in i_l..index_bases {
                    let jj = map_gen.genome_sa_index_start[i_l1].wrapping_add(ind0[i_l1]);
                    let jj_usize = jj as usize;
                    if jj_usize < sai.len() {
                        sai[jj_usize] |= map_gen.sai_mark_nmask_c;
                    }
                }
                break;
            }

            if ind_pref > ind0[i_l] || isa == 0 {
                let jj = map_gen.genome_sa_index_start[i_l].wrapping_add(ind_pref);
                let jj_usize = jj as usize;
                if jj_usize >= sai.len() {
                    return Err("BUG: SA index write is out of bounds\n".to_string());
                }
                sai[jj_usize] = isa as u32;

                let mut ii = ind0[i_l].wrapping_add(1);
                while ii < ind_pref {
                    let jj_absent = map_gen.genome_sa_index_start[i_l].wrapping_add(ii);
                    let jj_absent_usize = jj_absent as usize;
                    if jj_absent_usize >= sai.len() {
                        return Err("BUG: SA absent-index write is out of bounds\n".to_string());
                    }
                    sai[jj_absent_usize] = isa as u32 | map_gen.sai_mark_absent_mask_c;
                    ii = ii.wrapping_add(1);
                }
                ind0[i_l] = ind_pref;
            } else if ind_pref < ind0[i_l] {
                return Err("BUG: next index is smaller than previous, EXITING\n".to_string());
            }
        }

        genomesaindex_l178_funsaifindnextindex(
            g,
            sa,
            isa_step,
            &mut isa,
            &mut ind_full,
            &mut i_l4,
            map_gen,
        );
    }

    for i_l in 0..index_bases {
        let mut ii = map_gen.genome_sa_index_start[i_l]
            .wrapping_add(ind0[i_l])
            .wrapping_add(1);
        while ii < map_gen.genome_sa_index_start[i_l + 1] {
            let ii_usize = ii as usize;
            if ii_usize >= sai.len() {
                return Err("BUG: SA tail-index write is out of bounds\n".to_string());
            }
            sai[ii_usize] = map_gen.n_sa | map_gen.sai_mark_absent_mask_c;
            ii = ii.wrapping_add(1);
        }
    }

    Ok(())
}

#[doc = "Original `funSAiFindNextIndex` at STAR/source/genomeSAindex.cpp:178. Args: G: char, SA: PackedArray, isaStep: uint, isa: uint, indFull: uint, iL4: int, mapGen: Genome"]
pub fn genomesaindex_l178_funsaifindnextindex(
    g: &[u8],
    sa: &[u64],
    isa_step: u64,
    isa: &mut u64,
    ind_full: &mut u64,
    i_l4: &mut i32,
    map_gen: &crate::generated::structs::Genome,
) {
    let ind_full_prev = *ind_full;
    let i_l4_prev = *i_l4;
    *isa += isa_step;
    while *isa < map_gen.n_sa as u64 {
        *ind_full = suffixarrayfuns_l353_funcalcsaifromsa(
            g,
            sa,
            map_gen.n_genome,
            map_gen.gstrand_bit as u8,
            map_gen.gstrand_mask as u64,
            *isa,
            map_gen.p_ge.g_saindex_nbases as i32,
            i_l4,
        );
        if *ind_full != ind_full_prev || *i_l4 != i_l4_prev {
            break;
        }
        *isa += isa_step;
    }

    if *isa >= map_gen.n_sa as u64 {
        *ind_full = suffixarrayfuns_l353_funcalcsaifromsa(
            g,
            sa,
            map_gen.n_genome,
            map_gen.gstrand_bit as u8,
            map_gen.gstrand_mask as u64,
            map_gen.n_sa as u64 - 1,
            map_gen.p_ge.g_saindex_nbases as i32,
            i_l4,
        );
        if *ind_full == ind_full_prev && *i_l4 == i_l4_prev {
            *isa = map_gen.n_sa as u64;
            return;
        }
    }

    let mut i1 = *isa - isa_step;
    let mut i2 = std::cmp::min(*isa, map_gen.n_sa as u64 - 1);
    while i1 + 1 < i2 {
        *isa = i1 / 2 + i2 / 2 + (i1 % 2 + i2 % 2) / 2;
        *ind_full = suffixarrayfuns_l353_funcalcsaifromsa(
            g,
            sa,
            map_gen.n_genome,
            map_gen.gstrand_bit as u8,
            map_gen.gstrand_mask as u64,
            *isa,
            map_gen.p_ge.g_saindex_nbases as i32,
            i_l4,
        );
        if *ind_full == ind_full_prev && *i_l4 == i_l4_prev {
            i1 = *isa;
        } else {
            i2 = *isa;
        }
    }
    if *isa == i1 {
        *isa = i2;
        *ind_full = suffixarrayfuns_l353_funcalcsaifromsa(
            g,
            sa,
            map_gen.n_genome,
            map_gen.gstrand_bit as u8,
            map_gen.gstrand_mask as u64,
            *isa,
            map_gen.p_ge.g_saindex_nbases as i32,
            i_l4,
        );
    }
}

#[doc = "Original `GTF::transcriptGeneSJ` at STAR/source/GTF_transcriptGeneSJ.cpp:23. Args: dirOut: string"]
pub fn gtf_transcriptgenesj_l23_gtf_transcriptgenesj(
    gtf: &mut crate::generated::structs::GTF,
    genome: &crate::generated::structs::Genome,
    sjdb_loci: &mut crate::generated::structs::SjdbClass,
    _dir_out: &str,
    log_main: &mut String,
) -> crate::generated::structs::GtfTranscriptGeneSjOutput {
    let mut out = crate::generated::structs::GtfTranscriptGeneSjOutput::default();
    if !gtf.gtf_yes {
        return out;
    }

    gtf.exon_n = gtf.exon_loci.len() as u64;
    gtf.exon_loci.sort_by_key(|ex| (ex[GTF_EX_T], ex[GTF_EX_S]));

    let exon_n = gtf.exon_n as usize;
    let mut exge_loci = Vec::<[u64; 5]>::with_capacity(exon_n);
    for exon in &gtf.exon_loci {
        exge_loci.push([
            exon[GTF_EX_S],
            exon[GTF_EX_E],
            gtf.transcript_strand[exon[GTF_EX_T] as usize] as u64,
            exon[GTF_EX_G],
            exon[GTF_EX_T],
        ]);
    }
    exge_loci.sort();

    out.exon_ge_tr_info_tab
        .push_str(&format!("{}\n", gtf.exon_n));
    for exge in &exge_loci {
        out.exon_ge_tr_info_tab.push_str(&format!(
            "{}\t{}\t{}\t{}\t{}\n",
            exge[0], exge[1], exge[2], exge[3], exge[4]
        ));
    }

    out.gene_info_tab
        .push_str(&format!("{}\n", gtf.gene_id.len()));
    for ig in 0..gtf.gene_id.len() {
        out.gene_info_tab.push_str(&format!(
            "{}\t{}\t{}\n",
            gtf.gene_id[ig], gtf.gene_attr[ig][0], gtf.gene_attr[ig][1]
        ));
    }

    let mut extr_loci = Vec::<[u64; 6]>::with_capacity(exon_n);
    if exon_n > 0 {
        extr_loci.resize(exon_n, [0; 6]);
        let mut trex1 = 0usize;
        for iex in 0..=exon_n {
            if iex == exon_n || gtf.exon_loci[iex][GTF_EX_T] != gtf.exon_loci[trex1][GTF_EX_T] {
                for iex1 in trex1..iex {
                    extr_loci[iex1][1] = gtf.exon_loci[iex - 1][GTF_EX_E];
                }
                if iex == exon_n {
                    break;
                }
                trex1 = iex;
            }
            extr_loci[iex][0] = gtf.exon_loci[trex1][GTF_EX_S];
            extr_loci[iex][2] = gtf.exon_loci[iex][GTF_EX_T];
            extr_loci[iex][3] = gtf.exon_loci[iex][GTF_EX_S];
            extr_loci[iex][4] = gtf.exon_loci[iex][GTF_EX_E];
            extr_loci[iex][5] = gtf.exon_loci[iex][GTF_EX_G];
        }
    }
    extr_loci.sort_by(|a, b| a[..5].cmp(&b[..5]));

    out.transcript_info_tab
        .push_str(&format!("{}\n", gtf.transcript_id.len()));
    out.exon_info_tab.push_str(&format!("{}\n", gtf.exon_n));
    if exon_n > 0 {
        let mut trid = extr_loci[0][2];
        let mut trex = 0usize;
        let mut trstart = extr_loci[0][0];
        let mut trend = extr_loci[0][1];
        let mut exlen = 0u64;
        for iex in 0..=exon_n {
            if iex == exon_n || extr_loci[iex][2] != trid {
                out.transcript_info_tab.push_str(&format!(
                    "{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",
                    gtf.transcript_id[trid as usize],
                    extr_loci[iex - 1][0],
                    extr_loci[iex - 1][1],
                    trend,
                    gtf.transcript_strand[trid as usize],
                    iex - trex,
                    trex,
                    extr_loci[iex - 1][5]
                ));
                if iex == exon_n {
                    break;
                }
                trid = extr_loci[iex][2];
                trstart = extr_loci[iex][0];
                trex = iex;
                trend = std::cmp::max(trend, extr_loci[iex - 1][1]);
                exlen = 0;
            }
            out.exon_info_tab.push_str(&format!(
                "{}\t{}\t{}\n",
                extr_loci[iex][3] - trstart,
                extr_loci[iex][4] - trstart,
                exlen
            ));
            exlen += extr_loci[iex][4] - extr_loci[iex][3] + 1;
        }
    }

    let mut sj_loci = Vec::<[u64; 4]>::new();
    if exon_n > 0 {
        let mut tr_id_n = gtf.exon_loci[0][GTF_EX_T];
        for iex in 1..exon_n {
            if tr_id_n == gtf.exon_loci[iex][GTF_EX_T] {
                if gtf.exon_loci[iex][GTF_EX_S] <= gtf.exon_loci[iex - 1][GTF_EX_E] + 1 {
                } else if gtf.exon_loci[iex][GTF_EX_S] <= gtf.exon_loci[iex - 1][GTF_EX_E] {
                    let chr1 = genome.chr_bin
                        [(gtf.exon_loci[iex][GTF_EX_S] >> genome.p_ge.g_chr_bin_nbits) as usize]
                        as usize;
                    log_main.push_str(&format!(
                        "WARNING: while processing pGe.sjdbGTFfile={}: overlapping exons:\n",
                        genome.p_ge.sjdb_gtf_file
                    ));
                    log_main.push_str(&format!(
                        "{}\t{}\t{}\n",
                        genome.chr_name[chr1],
                        gtf.exon_loci[iex - 1][GTF_EX_S] + 1 - genome.chr_start[chr1],
                        gtf.exon_loci[iex - 1][GTF_EX_E] + 1 - genome.chr_start[chr1]
                    ));
                    log_main.push_str(&format!(
                        "{}\t{}\t{}\n",
                        genome.chr_name[chr1],
                        gtf.exon_loci[iex][GTF_EX_S] + 1 - genome.chr_start[chr1],
                        gtf.exon_loci[iex][GTF_EX_E] + 1 - genome.chr_start[chr1]
                    ));
                } else {
                    sj_loci.push([
                        gtf.exon_loci[iex - 1][GTF_EX_E] + 1,
                        gtf.exon_loci[iex][GTF_EX_S] - 1,
                        gtf.transcript_strand[tr_id_n as usize] as u64,
                        gtf.exon_loci[iex][GTF_EX_G] + 1,
                    ]);
                }
            } else {
                tr_id_n = gtf.exon_loci[iex][GTF_EX_T];
            }
        }
    }
    sj_loci.sort_by_key(|sj| (sj[0], sj[1]));

    let strand_char = ['.', '+', '-'];
    let sjdb_n1 = sjdb_loci.chr.len();
    sjdb_loci
        .gene
        .resize(sjdb_n1, std::collections::BTreeSet::new());
    for ii in 0..sj_loci.len() {
        if ii == 0
            || sj_loci[ii][0] != sj_loci[ii - 1][0]
            || sj_loci[ii][1] != sj_loci[ii - 1][1]
            || sj_loci[ii][2] != sj_loci[ii - 1][2]
        {
            let chr1 =
                genome.chr_bin[(sj_loci[ii][0] >> genome.p_ge.g_chr_bin_nbits) as usize] as usize;
            sjdb_loci.chr.push(genome.chr_name[chr1].clone());
            sjdb_loci
                .start
                .push(sj_loci[ii][0] + 1 - genome.chr_start[chr1]);
            sjdb_loci
                .end
                .push(sj_loci[ii][1] + 1 - genome.chr_start[chr1]);
            sjdb_loci.str_.push(strand_char[sj_loci[ii][2] as usize]);
            sjdb_loci
                .gene
                .push(std::iter::once(sj_loci[ii][3]).collect());
        } else if let Some(gene) = sjdb_loci.gene.last_mut() {
            gene.insert(sj_loci[ii][3]);
        }
    }

    for ii in sjdb_n1..sjdb_loci.chr.len() {
        out.sjdb_list_from_gtf_out_tab.push_str(&format!(
            "{}\t{}\t{}\t{}",
            sjdb_loci.chr[ii], sjdb_loci.start[ii], sjdb_loci.end[ii], sjdb_loci.str_[ii]
        ));
        let mut genes = sjdb_loci.gene[ii].iter();
        if let Some(first) = genes.next() {
            out.sjdb_list_from_gtf_out_tab
                .push_str(&format!("\t{}", first));
            for gene in genes {
                out.sjdb_list_from_gtf_out_tab
                    .push_str(&format!(",{}", gene));
            }
        }
        out.sjdb_list_from_gtf_out_tab.push('\n');
    }

    sjdb_loci.priority.resize(sjdb_loci.chr.len(), 20);
    let added = sjdb_loci.chr.len() - sjdb_n1;
    log_main.push_str(&format!(
        "Processing pGe.sjdbGTFfile={}, found:\n\t\t{} transcripts\n\t\t{} exons (non-collapsed)\n\t\t{} collapsed junctions\nTotal junctions: {}\n",
        genome.p_ge.sjdb_gtf_file,
        gtf.transcript_id.len(),
        gtf.exon_n,
        added,
        sjdb_loci.chr.len()
    ));
    log_main.push_str(" ..... finished GTF processing\n\n");

    out.n_junctions_added = added as u64;
    out
}

#[doc = "Original `SoloReadFeature::inputRecords` at STAR/source/SoloReadFeature_inputRecords.cpp:8. Args: cbP: uint32, cbPstride: uint32, cbReadCountTotal: vector<uint32>, readInfo: vector<readInfoStruct>, readFlagCounts: SoloReadFlagClass, nReadPerCBunique1: vector<uint32>, nReadPerCBmulti1: vector<uint32>"]
pub fn soloreadfeature_inputrecords_l8_soloreadfeature_inputrecords(
    rf: &mut crate::generated::structs::SoloReadFeature,
    p_solo: &crate::generated::structs::ParametersSolo,
    sj_all: &[Vec<u64>; 2],
    cb_p: &mut [Vec<u32>],
    cb_p_stride: u32,
    cb_read_count_total: &[u32],
    read_info: &mut [crate::generated::structs::SoloFeatureReadInfo],
    read_flag_counts: &mut crate::generated::structs::SoloReadFlagClass,
    n_read_per_cb_unique1: &mut [u32],
    n_read_per_cb_multi1: &mut [u32],
) {
    let mut prev_iread = u64::MAX;
    let mut tr_id_dist = Vec::<u32>::new();

    for line in rf.stream_reads.lines() {
        let mut tokens = line.split_whitespace();
        let mut feature = 0_u32;
        let mut umi = 0_u64;
        let mut iread = 0_u64;
        let mut cbmatch = 0_i32;

        if !soloinputfeatureumi_l5_soloinputfeatureumi(
            &mut tokens,
            rf.feature_type,
            rf.read_index_yes,
            sj_all,
            &mut iread,
            &mut cbmatch,
            &mut feature,
            &mut umi,
            &mut tr_id_dist,
            read_flag_counts,
        ) {
            break;
        }

        if feature == u32::MAX && !rf.read_index_yes {
            continue;
        }

        let mut read_is_counted = false;
        let feat_good = feature != u32::MAX;
        let mut no_mm_to_wl_without_exact = false;
        let mut no_too_many_wl_matches = false;
        let mut cb = -1_i64;

        if cbmatch <= 1 {
            cb = tokens.next().unwrap().parse::<i64>().unwrap();
            if p_solo.cb_match_wl.one_exact && cbmatch == 1 && cb_read_count_total[cb as usize] == 0
            {
                no_mm_to_wl_without_exact = true;
            } else {
                if !p_solo.cb_wl_yes {
                    cb = servicefuns_l294_binarysearchexact(
                        cb as u64,
                        &p_solo.cb_wl,
                        p_solo.cb_wl_size as u64,
                    );
                    if cb + 1 == 0 {
                        continue;
                    }
                }

                if feat_good {
                    read_is_counted = true;
                    let cb_index = cb as usize;
                    let old_len = cb_p[cb_index].len();
                    cb_p[cb_index].resize(old_len + cb_p_stride as usize, 0);
                    cb_p[cb_index][old_len] = feature;
                    cb_p[cb_index][old_len + 1] = umi as u32;
                    if rf.read_index_yes {
                        cb_p[cb_index][old_len + 2] = iread as u32;
                    }
                } else if rf.read_info_yes {
                    read_info[iread as usize].cb = cb;
                    read_info[iread as usize].umi = umi;
                }
            }
        } else {
            let mut ptot = 0.0_f64;
            let mut pmax = 0.0_f64;
            for _ in 0..cbmatch as u32 {
                let cbin = tokens.next().unwrap().parse::<u32>().unwrap();
                let qin_token = tokens.next().unwrap();
                let mut qin = qin_token.as_bytes()[0] as i32 - p_solo.qs_base as i32;
                qin = std::cmp::min(qin, p_solo.qs_max as i32);
                if cb_read_count_total[cbin as usize] > 0 {
                    let pin = cb_read_count_total[cbin as usize] as f64
                        * 10.0_f64.powf(-qin as f64 / 10.0);
                    ptot += pin;
                    if pin > pmax {
                        cb = cbin as i64;
                        pmax = pin;
                    }
                }
            }

            if ptot > 0.0 && pmax >= p_solo.cb_min_p * ptot {
                if feat_good {
                    read_is_counted = true;
                    let cb_index = cb as usize;
                    let old_len = cb_p[cb_index].len();
                    cb_p[cb_index].resize(old_len + cb_p_stride as usize, 0);
                    cb_p[cb_index][old_len] = feature;
                    cb_p[cb_index][old_len + 1] = umi as u32;
                    if rf.read_index_yes {
                        cb_p[cb_index][old_len + 2] = iread as u32;
                    }
                } else if rf.read_info_yes {
                    read_info[iread as usize].cb = cb;
                    read_info[iread as usize].umi = umi;
                }
            } else {
                no_too_many_wl_matches = true;
            }
        }

        if !rf.read_index_yes || iread != prev_iread {
            prev_iread = iread;
            if feat_good {
                if cbmatch == 0 {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_YES_SUB_WL_MATCH_EXACT] += 1;
                } else if no_mm_to_wl_without_exact {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_NO_MM_TO_WL_WITHOUT_EXACT] += 1;
                } else if no_too_many_wl_matches {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_NO_TOO_MANY_WL_MATCHES] += 1;
                }
            }

            if read_is_counted {
                if feature < (1_u32 << 31) {
                    n_read_per_cb_unique1[cb as usize] += 1;
                } else {
                    n_read_per_cb_multi1[cb as usize] += 1;
                }
            }

            let read_stats_yes = p_solo
                .read_stats_yes
                .get(rf.feature_type as usize)
                .copied()
                .unwrap_or(false);
            if read_stats_yes {
                if read_is_counted {
                    if (read_flag_counts.flag >> SOLO_READ_FLAG_FEATURE_U) & 1 != 0 {
                        read_flag_counts.flag |= 1_u32 << SOLO_READ_FLAG_COUNTED_U;
                    }
                    if (read_flag_counts.flag >> SOLO_READ_FLAG_FEATURE_M) & 1 != 0 {
                        read_flag_counts.flag |= 1_u32 << SOLO_READ_FLAG_COUNTED_M;
                    }
                }

                read_flag_counts.flag |= 1_u32 << SOLO_READ_FLAG_CB_MATCH;
                if cbmatch == 0 {
                    read_flag_counts.flag |= 1_u32 << SOLO_READ_FLAG_CB_PERFECT;
                    let counts = read_flag_counts
                        .flag_counts
                        .entry(cb as u64)
                        .or_insert([0; SOLO_READ_FLAG_N_BITS]);
                    for ibit in 0..SOLO_READ_FLAG_N_BITS {
                        counts[ibit] += ((read_flag_counts.flag >> ibit) & 1_u32) as u64;
                    }
                } else if cbmatch == 1 && !no_mm_to_wl_without_exact {
                    read_flag_counts.flag |= 1_u32 << SOLO_READ_FLAG_CB_MM_UNIQUE;
                    let counts = read_flag_counts
                        .flag_counts
                        .entry(cb as u64)
                        .or_insert([0; SOLO_READ_FLAG_N_BITS]);
                    for ibit in 0..SOLO_READ_FLAG_N_BITS {
                        counts[ibit] += ((read_flag_counts.flag >> ibit) & 1_u32) as u64;
                    }
                } else if cbmatch > 1 && !no_too_many_wl_matches {
                    read_flag_counts.flag |= 1_u32 << SOLO_READ_FLAG_CB_MM_MULTIPLE;
                    let counts = read_flag_counts
                        .flag_counts
                        .entry(cb as u64)
                        .or_insert([0; SOLO_READ_FLAG_N_BITS]);
                    for ibit in 0..SOLO_READ_FLAG_N_BITS {
                        counts[ibit] += ((read_flag_counts.flag >> ibit) & 1_u32) as u64;
                    }
                } else {
                    for ibit in 0..SOLO_READ_FLAG_N_BITS {
                        read_flag_counts.flag_counts_no_cb[ibit] +=
                            ((read_flag_counts.flag >> ibit) & 1_u32) as u64;
                    }
                }
            }
        }
    }
}

