#[doc = "Original `ReadAlign::calcCIGAR` at STAR/source/ReadAlign_calcCIGAR.cpp:3. Args: trOut: Transcript, nMates: uint, iExMate: uint, leftMate: uint"]
pub fn readalign_calccigar_l3_readalign_calccigar(
    read_align: &mut crate::generated::structs::ReadAlign,
    tr_out: &crate::generated::structs::Transcript,
    n_mates: u32,
    i_ex_mate: u32,
    left_mate: u32,
) {
    read_align.mates_cigar.clear();
    for imate in 0..n_mates {
        let i_ex1 = if imate == 0 { 0 } else { i_ex_mate + 1 };
        let i_ex2 = if imate == 0 {
            i_ex_mate
        } else {
            tr_out.n_exons - 1
        };
        let mate = tr_out.exons[i_ex1 as usize][EX_IFRAG] as usize;
        let str_ = tr_out.str_ as usize;

        let mut cigar = String::new();

        let trim_l = if str_ == 0 && mate == 0 {
            read_align.clip_mates[mate][0].clipped_n
        } else if str_ == 0 && mate == 1 {
            read_align.clip_mates[mate][1].clipped_n
        } else if str_ == 1 && mate == 0 {
            read_align.clip_mates[mate][1].clipped_n
        } else {
            read_align.clip_mates[mate][0].clipped_n
        };

        let left_mate_usize = left_mate as usize;
        let trim_l1 = trim_l + tr_out.exons[i_ex1 as usize][EX_R]
            - if tr_out.exons[i_ex1 as usize][EX_R] < read_align.read_length[left_mate_usize] {
                0
            } else {
                read_align.read_length[left_mate_usize] + 1
            };
        if trim_l1 > 0 {
            cigar.push_str(&format!("{}S", trim_l1));
        }

        for ii in i_ex1..=i_ex2 {
            let ii_usize = ii as usize;
            if ii > i_ex1 {
                let prev = ii_usize - 1;
                let gap_g = tr_out.exons[ii_usize][EX_G]
                    - (tr_out.exons[prev][EX_G] + tr_out.exons[prev][EX_L]);
                let gap_r = tr_out.exons[ii_usize][EX_R]
                    - tr_out.exons[prev][EX_R]
                    - tr_out.exons[prev][EX_L];
                if gap_r > 0 {
                    cigar.push_str(&format!("{}I", gap_r));
                }
                if tr_out.canon_sj[prev] >= 0 || tr_out.sj_annot[prev] == 1 {
                    cigar.push_str(&format!("{}N", gap_g));
                } else if gap_g > 0 {
                    cigar.push_str(&format!("{}D", gap_g));
                }
            }
            cigar.push_str(&format!("{}M", tr_out.exons[ii_usize][EX_L]));
        }

        let i_ex1_usize = i_ex1 as usize;
        let i_ex2_usize = i_ex2 as usize;
        let trim_r1 = (if tr_out.exons[i_ex1_usize][EX_R] < read_align.read_length[left_mate_usize]
        {
            read_align.read_length_original[left_mate_usize]
        } else {
            read_align.read_length[left_mate_usize] + 1 + read_align.read_length_original[mate]
        }) - tr_out.exons[i_ex2_usize][EX_R]
            - tr_out.exons[i_ex2_usize][EX_L]
            - trim_l;
        if trim_r1 > 0 {
            cigar.push_str(&format!("{}S", trim_r1));
        }
        read_align.mates_cigar.push(cigar);
    }
}

#[doc = "Original `signalFromBAM` at STAR/source/signalFromBAM.cpp:5. Args: bamFileName: string, sigFileName: string, P: Parameters"]
pub fn signalfrombam_l5_signalfrombam(
    sig_file_name: &str,
    p: &crate::generated::structs::Parameters,
    target_names: &[String],
    target_lens: &[u32],
    records: &[crate::generated::structs::SignalFromBamRecord],
) -> Result<crate::generated::structs::SignalFromBamResult, String> {
    let mut n_mult = 0.0_f64;
    let mut n_uniq = 0.0_f64;
    let prefix = if p.out_wig_references_prefix.is_empty() {
        "-"
    } else {
        p.out_wig_references_prefix.as_str()
    };

    if p.out_wig_flags.norm == 1 {
        for rec in records {
            if rec.tid < 0 {
                continue;
            }
            let tid = rec.tid as usize;
            if prefix != "-" && !target_names[tid].starts_with(prefix) {
                continue;
            }
            if let Some(nh) = rec.nh {
                if nh == 1 {
                    n_uniq += 1.0;
                } else if nh > 1 {
                    n_mult += 1.0 / nh as f64;
                }
            }
        }
    }

    let sig_n = if p.out_wig_flags.strand { 4 } else { 2 };
    let mut sig_out_file_names = Vec::with_capacity(sig_n as usize);
    sig_out_file_names.push(format!("{sig_file_name}.Unique.str1.out"));
    sig_out_file_names.push(format!("{sig_file_name}.UniqueMultiple.str1.out"));
    if p.out_wig_flags.strand {
        sig_out_file_names.push(format!("{sig_file_name}.Unique.str2.out"));
        sig_out_file_names.push(format!("{sig_file_name}.UniqueMultiple.str2.out"));
    }
    for name in &mut sig_out_file_names {
        name.push_str(if p.out_wig_flags.format == 0 {
            ".bg"
        } else {
            ".wig"
        });
    }

    let mut norm_factor = vec![1.0_f64; sig_n as usize];
    if p.out_wig_flags.norm == 1 {
        norm_factor[0] = 1.0e6 / n_uniq;
        norm_factor[1] = 1.0e6 / (n_uniq + n_mult);
    }
    if p.out_wig_flags.strand {
        norm_factor[2] = norm_factor[0];
        norm_factor[3] = norm_factor[1];
    }

    let mut files = std::collections::BTreeMap::<String, String>::new();
    for name in &sig_out_file_names {
        files.insert(name.clone(), String::new());
    }

    let mut i_chr = -999_i32;
    let mut sig_all = Vec::<f64>::new();
    let mut chr_len = 0_u32;

    for rec_opt in records.iter().map(Some).chain(std::iter::once(None)) {
        let bam_bytes_negative = rec_opt.is_none();
        let rec_tid = rec_opt.map(|rec| rec.tid).unwrap_or(i_chr);
        if rec_tid != i_chr || bam_bytes_negative {
            if i_chr != -999 {
                let chr_name = &target_names[i_chr as usize];
                for is in 0..sig_n as usize {
                    let out = files.get_mut(&sig_out_file_names[is]).unwrap();
                    if p.out_wig_flags.format == 1 {
                        out.push_str(&format!("variableStep chrom={chr_name}\n"));
                    }
                    let mut prev_sig = 0.0_f64;
                    for ig in 0..chr_len as usize {
                        let new_sig = sig_all[sig_n as usize * ig + is];
                        if p.out_wig_flags.format == 0 {
                            if new_sig != prev_sig {
                                if prev_sig != 0.0 {
                                    if p.out_wig_flags.norm == 1 {
                                        out.push_str(&format!(
                                            "{}\t{:.5}\n",
                                            ig,
                                            prev_sig * norm_factor[is]
                                        ));
                                    } else {
                                        out.push_str(&format!(
                                            "{}\t{}\n",
                                            ig,
                                            prev_sig * norm_factor[is]
                                        ));
                                    }
                                }
                                if new_sig != 0.0 {
                                    out.push_str(&format!("{chr_name}\t{ig}\t"));
                                }
                                prev_sig = new_sig;
                            }
                        } else if p.out_wig_flags.format == 1 && new_sig != 0.0 {
                            if p.out_wig_flags.norm == 1 {
                                out.push_str(&format!(
                                    "{}\t{:.5}\n",
                                    ig + 1,
                                    new_sig * norm_factor[is]
                                ));
                            } else {
                                out.push_str(&format!(
                                    "{}\t{}\n",
                                    ig + 1,
                                    new_sig * norm_factor[is]
                                ));
                            }
                        }
                    }
                }
            }
            if bam_bytes_negative {
                break;
            }

            let rec = rec_opt.unwrap();
            i_chr = rec.tid;
            if i_chr == -1 || (prefix != "-" && !target_names[rec.tid as usize].starts_with(prefix))
            {
                i_chr = -999;
                continue;
            }
            chr_len = target_lens[rec.tid as usize] + 1;
            sig_all = vec![0.0; sig_n as usize * chr_len as usize];
        }

        let rec = rec_opt.unwrap();
        if (rec.flag & 0x400) > 0 {
            continue;
        }
        let a_nh = rec.nh.unwrap_or(1);
        if a_nh == 0 {
            continue;
        }
        let mut a_g = rec.pos;
        let mut i_strand = 0_u32;
        if p.out_wig_flags.strand {
            i_strand = u32::from(((rec.flag & 0x10) > 0) == ((rec.flag & 0x80) == 0));
        }

        if p.out_wig_flags.type_ == 1 {
            if (rec.flag & 0x80) > 0 {
                continue;
            }
            if i_strand == 0 {
                if a_nh == 1 {
                    sig_all[(a_g * sig_n as u32 + 2 * i_strand) as usize] += 1.0;
                }
                sig_all[(a_g * sig_n as u32 + 1 + 2 * i_strand) as usize] += 1.0 / a_nh as f64;
                continue;
            }
        }

        for &cig in &rec.cigar {
            let cig_op = cig & 0xf;
            let cig_l = cig >> 4;
            match cig_op {
                BAM_CIGAR_D | BAM_CIGAR_N => {
                    a_g += cig_l;
                }
                BAM_CIGAR_M => {
                    if p.out_wig_flags.type_ == 0
                        || (p.out_wig_flags.type_ == 2 && (rec.flag & 0x80) > 0)
                    {
                        for _ in 0..cig_l {
                            if a_g >= chr_len {
                                return Err(
                                    "BUG: alignment extends past chromosome in signalFromBAM.cpp\n"
                                        .to_string(),
                                );
                            }
                            if a_nh == 1 {
                                sig_all[(a_g * sig_n as u32 + 2 * i_strand) as usize] += 1.0;
                            }
                            sig_all[(a_g * sig_n as u32 + 1 + 2 * i_strand) as usize] +=
                                1.0 / a_nh as f64;
                            a_g += 1;
                        }
                    } else {
                        a_g += cig_l;
                    }
                }
                _ => {}
            }
        }
        if p.out_wig_flags.type_ == 1 {
            a_g = a_g.wrapping_sub(1);
            if a_nh == 1 {
                sig_all[(a_g * sig_n as u32 + 2 * i_strand) as usize] += 1.0;
            }
            sig_all[(a_g * sig_n as u32 + 1 + 2 * i_strand) as usize] += 1.0 / a_nh as f64;
        }
    }

    Ok(crate::generated::structs::SignalFromBamResult {
        files,
        n_unique: n_uniq,
        n_multiple: n_mult,
    })
}

#[doc = "Original `SoloFeature::quantTranscript` at STAR/source/SoloFeature_quantTranscript.cpp:12. Args: "]
pub fn solofeature_quanttranscript_l12_solofeature_quanttranscript(
    solo_feature: &mut crate::generated::structs::SoloFeature,
    p_solo: &crate::generated::structs::ParametersSolo,
    trans: &crate::generated::structs::Transcriptome,
    run_thread_n: i32,
    cluster_contents: &str,
    time_finished_input: &str,
    time_finished_cluster_prefix: &str,
    time_finished_quantification: &str,
) -> crate::generated::structs::SoloFeatureQuantTranscriptResult {
    let mut result = crate::generated::structs::SoloFeatureQuantTranscriptResult::default();
    if p_solo.cluster_cb_file == "-" {
        result.returned_no_cluster_file = true;
        return result;
    }

    let mut cluster_cb_ind = std::collections::BTreeMap::<u32, u32>::new();
    let mut cluster_ind = std::collections::BTreeSet::<u32>::new();
    let mut words = cluster_contents.split_whitespace();
    while let Some(seq1) = words.next() {
        let Some(icl1s) = words.next() else {
            break;
        };
        let icl1 = icl1s.parse::<u32>().unwrap_or(0);
        let mut cb1 = 0_u64;
        if sequencefuns_l249_convertnuclstrtoint64(seq1, &mut cb1) != 0 {
            let cb1ind = p_solo.cb_wl.partition_point(|x| *x < cb1) as u32;
            if cb1ind < p_solo.cb_wl.len() as u32 {
                cluster_cb_ind.insert(cb1ind, icl1);
                cluster_ind.insert(icl1);
            } else {
                result.log_main.push_str(&format!(
                    "WARNING: cluster CB sequence not present in whitelist and is ignored: {}\n",
                    seq1
                ));
            }
        } else {
            result.log_main.push_str(&format!(
                "WARNING: cluster CB sequence contains non-ACGT base and is ignored: {}\n",
                seq1
            ));
        }
    }

    let tr_dist_count = solo_feature
        .read_feat_sum
        .as_ref()
        .map(|rf| rf.transcript_dist_count.clone())
        .unwrap_or_default();
    let mut tr_dist_fun = vec![0.0_f64; tr_dist_count.len()];
    let mut tr_dist_fun_tr_factor = vec![0.0_f64; trans.n_tr as usize];

    let run_aver_n = 50_i32;
    let run_aver_start = 0_i32;
    for ii in 0..run_aver_start as usize {
        tr_dist_fun[ii] = tr_dist_count[ii] as f64;
    }
    let upper = tr_dist_count.len() as i32 - run_aver_n - 1;
    for ii in run_aver_start..upper {
        let start = std::cmp::max(run_aver_start, ii - run_aver_n) as usize;
        let end = (ii + run_aver_n + 1) as usize;
        let sum: u32 = tr_dist_count[start..end].iter().sum();
        let denom = std::cmp::min(2 * run_aver_n + 1, ii - run_aver_start + run_aver_n);
        tr_dist_fun[ii as usize] = sum as f64 / denom as f64;
    }

    let mut imax = 1000_usize;
    while imax + 1 < tr_dist_fun.len() && tr_dist_fun[imax + 1] > tr_dist_fun[imax] {
        imax += 1;
    }
    result.log_main.push_str(&format!(
        "SoloQuant: distance distribution past maximum = {}\n",
        imax
    ));
    while imax + 1 < tr_dist_fun.len() && tr_dist_fun[imax + 1] < tr_dist_fun[imax] {
        imax += 1;
    }
    result.log_main.push_str(&format!(
        "SoloQuant: distance distribution cutoff = {}\n",
        imax
    ));
    tr_dist_fun.truncate(imax);

    let norm1: f64 = tr_dist_fun.iter().sum();
    let mut dist_file = String::new();
    if norm1 != 0.0 {
        for ff in &mut tr_dist_fun {
            *ff /= norm1;
            dist_file.push_str(&format!("{}\n", *ff));
        }
    }
    result.files.insert(
        format!(
            "{}transcriptEndDistanceDistribution.txt",
            solo_feature.output_prefix
        ),
        dist_file,
    );

    let mut tr_dist_fun_cum = tr_dist_fun.clone();
    for ii in 1..tr_dist_fun_cum.len() {
        tr_dist_fun_cum[ii] += tr_dist_fun_cum[ii - 1];
    }
    for ii in 0..trans.n_tr as usize {
        if trans.tr_len[ii] as usize <= tr_dist_fun_cum.len() && trans.tr_len[ii] > 0 {
            tr_dist_fun_tr_factor[ii] = -tr_dist_fun_cum[trans.tr_len[ii] as usize - 1].ln();
        }
    }
    for ff in &mut tr_dist_fun {
        *ff = ff.ln();
    }

    let mut map_tr_dist =
        std::collections::BTreeMap::<u32, std::collections::BTreeMap<u64, Vec<(u32, f64)>>>::new();
    for i_thread in 0..run_thread_n as usize {
        let Some(read_feat) = solo_feature.read_feat_all.get(i_thread) else {
            continue;
        };
        for line1 in read_feat.stream_reads.lines() {
            let mut fields = line1.split_whitespace();
            let Some(cb_s) = fields.next() else {
                continue;
            };
            let Some(umi_s) = fields.next() else {
                continue;
            };
            let Some(ntr_s) = fields.next() else {
                continue;
            };
            let cb = cb_s.parse::<u32>().unwrap_or(0);
            let mut umi = umi_s.parse::<u64>().unwrap_or(0);
            let n_tr = ntr_s.parse::<u32>().unwrap_or(0);
            let Some(cb_cl) = cluster_cb_ind.get(&cb).copied() else {
                for _ in 0..n_tr {
                    let _ = fields.next();
                    let _ = fields.next();
                }
                continue;
            };
            umi += (cb as u64) << 32;

            let mut td = Vec::<(u32, f64)>::with_capacity(n_tr as usize);
            for _ in 0..n_tr {
                let Some(tr1_s) = fields.next() else {
                    break;
                };
                let Some(d1_s) = fields.next() else {
                    break;
                };
                let tr1 = tr1_s.parse::<u32>().unwrap_or(0);
                let d1 = d1_s.parse::<usize>().unwrap_or(0);
                if d1 >= tr_dist_fun.len() || tr1 as usize >= tr_dist_fun_tr_factor.len() {
                    continue;
                }
                td.push((tr1, tr_dist_fun[d1] + tr_dist_fun_tr_factor[tr1 as usize]));
            }
            if td.is_empty() {
                continue;
            }
            td.sort_by_key(|x| x.0);

            let cl_map = map_tr_dist.entry(cb_cl).or_default();
            if let Some(old_td) = cl_map.get(&umi).cloned() {
                let mut inew = 0usize;
                let mut td1 = Vec::<(u32, f64)>::with_capacity(old_td.len());
                for old in old_td {
                    while inew < td.len() && old.0 > td[inew].0 {
                        inew += 1;
                    }
                    if inew == td.len() {
                        break;
                    }
                    if old.0 == td[inew].0 {
                        td1.push((td[inew].0, old.1 + td[inew].1));
                    }
                }
                cl_map.insert(umi, td1);
            } else {
                cl_map.insert(umi, td);
            }
        }
    }
    result.log_main.push_str(&format!(
        "{} ... Transcript3p counting: finished input\n",
        time_finished_input
    ));

    let mut cluster_expression = std::collections::BTreeMap::<u32, Vec<f64>>::new();
    for (cluster, mut cl_tr_dist) in map_tr_dist {
        let mut tr_unique = vec![0.0_f64; trans.n_tr as usize];
        let mut tr_initial = vec![0.0_f64; trans.n_tr as usize];
        let mut n_umi_tot = 0_u64;
        let mut n_umi0 = 0_u64;
        let mut n_umi1 = 0_u64;

        let keys: Vec<u64> = cl_tr_dist.keys().copied().collect();
        for key in keys {
            let Some(tr_dist) = cl_tr_dist.get_mut(&key) else {
                continue;
            };
            if tr_dist.is_empty() {
                cl_tr_dist.remove(&key);
                n_umi0 += 1;
            } else if tr_dist.len() == 1 {
                let tr = tr_dist[0].0 as usize;
                tr_unique[tr] += 1.0;
                tr_initial[tr] += 1.0;
                cl_tr_dist.remove(&key);
                n_umi1 += 1;
                n_umi_tot += 1;
            } else {
                let max1 = tr_dist
                    .iter()
                    .map(|td| td.1)
                    .fold(f64::NEG_INFINITY, f64::max);
                let tr_dist_len = tr_dist.len() as f64;
                for tt in tr_dist.iter_mut() {
                    tr_initial[tt.0 as usize] += 1.0 / tr_dist_len;
                    tt.1 = (tt.1 - max1).exp();
                }
                n_umi_tot += 1;
            }
        }
        result.log_main.push_str(&format!(
            "{} ... Transcript3p counting: cluster {} nUMItot={} nUMI0={} nUMI1={}\n",
            time_finished_input, cluster, n_umi_tot, n_umi0, n_umi1
        ));

        let mut th_old_new = [tr_initial, vec![0.0_f64; trans.n_tr as usize]];
        let mut old_i = 0usize;
        let mut new_i = 1usize;
        let mut tr_converged = vec![false; trans.n_tr as usize];
        for iteration in 0..10000_u32 {
            let (old_slice, new_slice): (Vec<f64>, &mut Vec<f64>) = {
                let old = th_old_new[old_i].clone();
                let new = &mut th_old_new[new_i];
                (old, new)
            };
            new_slice.copy_from_slice(&tr_unique);
            for tr_dist in cl_tr_dist.values() {
                let mut denom1 = 0.0_f64;
                for td in tr_dist {
                    denom1 += td.1 * old_slice[td.0 as usize];
                }
                for td in tr_dist {
                    if !tr_converged[td.0 as usize] && denom1 != 0.0 {
                        new_slice[td.0 as usize] += td.1 * old_slice[td.0 as usize] / denom1;
                    }
                }
            }

            let diff_threshold_max = 1e-5_f64;
            let diff_threshold_one = diff_threshold_max * 0.1;
            let expr_threshold = 1e-8_f64 * n_umi_tot as f64;
            let mut diff_max = 0.0_f64;
            let mut diff_sum = 0.0_f64;
            let mut above_thr_n = 0_u64;
            let mut above_thr_expr_sum = 0.0_f64;
            let mut above_thr_one_n = 0_u64;
            for itr in 0..new_slice.len() {
                if tr_converged[itr] || old_slice[itr] == 0.0 {
                    continue;
                }
                let diff1 = (new_slice[itr] - old_slice[itr]).abs() / old_slice[itr];
                diff_sum += diff1;
                diff_max = diff_max.max(diff1);
                if diff1 > diff_threshold_max {
                    above_thr_n += 1;
                    above_thr_expr_sum += new_slice[itr];
                }
                if new_slice[itr] < expr_threshold {
                    tr_converged[itr] = true;
                    tr_unique[itr] = 0.0;
                }
                if diff1 < diff_threshold_one {
                    tr_converged[itr] = true;
                    tr_unique[itr] = new_slice[itr];
                } else {
                    above_thr_one_n += 1;
                }
            }
            result.stdout.push_str(&format!(
                "{} {} {} {} {} {}\n",
                iteration, diff_max, diff_sum, above_thr_n, above_thr_expr_sum, above_thr_one_n
            ));
            if diff_max < diff_threshold_max {
                break;
            }
            std::mem::swap(&mut old_i, &mut new_i);
        }

        let mut th_out = th_old_new[new_i].clone();
        let mut norm = 0.0_f64;
        for itr in 0..th_out.len() {
            th_out[itr] *= tr_dist_fun_tr_factor[itr].exp();
            norm += th_out[itr];
        }
        if norm != 0.0 {
            norm = n_umi_tot as f64 / norm;
            for tt in &mut th_out {
                *tt *= norm;
            }
        }
        cluster_expression.insert(cluster, th_out);
        result.log_main.push_str(&format!(
            "{} ... Transcript3p counting: finished cluster{}\n",
            time_finished_cluster_prefix, cluster
        ));
    }

    let mut matrix = String::new();
    matrix.push_str("%%MatrixMarket matrix coordinate real general\n%\n");
    let mut n_cell_gene_entries = 0_u32;
    for ctpm in cluster_expression.values() {
        for tt in ctpm {
            if *tt > 0.0 {
                n_cell_gene_entries += 1;
            }
        }
    }
    let max_cluster = cluster_ind.iter().next_back().copied().unwrap_or(0);
    matrix.push_str(&format!(
        "{} {} {}\n",
        trans.n_tr, max_cluster, n_cell_gene_entries
    ));
    for (cluster, ctpm) in &cluster_expression {
        for (itr, value) in ctpm.iter().enumerate() {
            if *value > 0.0 {
                matrix.push_str(&format!("{} {} {}\n", itr + 1, cluster, value));
            }
        }
    }
    result.files.insert(
        format!(
            "{}{}",
            solo_feature.output_prefix,
            p_solo
                .out_file_names
                .get(3)
                .cloned()
                .unwrap_or_else(|| "matrix.mtx".to_string())
        ),
        matrix,
    );

    let mut features = String::new();
    for ii in 0..trans.n_tr as usize {
        let gene = trans.tr_gene.get(ii).copied().unwrap_or(0) as usize;
        features.push_str(&format!(
            "{}\t{}\t{}\n",
            trans.tr_id.get(ii).cloned().unwrap_or_default(),
            trans.tr_len.get(ii).copied().unwrap_or(0),
            trans.ge_name.get(gene).cloned().unwrap_or_default()
        ));
    }
    result.files.insert(
        format!("{}/features.tsv", solo_feature.output_prefix),
        features,
    );
    result.log_main.push_str(&format!(
        "{} ... Transcript3p counting: finished transcript quantification\n",
        time_finished_quantification
    ));
    result.cluster_expression = cluster_expression;
    result
}

#[doc = "Original `SoloFeature::processRecords` at STAR/source/SoloFeature_processRecords.cpp:8. Args: "]
pub fn solofeature_processrecords_l8_solofeature_processrecords<FCount, FQuant>(
    solo_feature: &mut crate::generated::structs::SoloFeature,
    p: &mut crate::generated::structs::Parameters,
    p_solo: &mut crate::generated::structs::ParametersSolo,
    read_bar_sum: &mut crate::generated::structs::SoloReadBarcode,
    read_feat_all: &[crate::generated::structs::SoloReadFeature],
    gene_solo_feature: Option<&crate::generated::structs::SoloFeature>,
    trans: &crate::generated::structs::Transcriptome,
    g_stats_all: &crate::generated::structs::Stats,
    ra_chunks: &[crate::generated::structs::ReadAlign],
    current_dir: &str,
    sj_start_gap_rows: &[(u64, u64)],
    time_start: &str,
    time_writing_raw_matrix: &str,
    time_cell_filtering: &str,
    time_finished_redistribution: &str,
    time_finished_collapsing: &str,
    time_finished_counting: &str,
    linux_proc_memory: &str,
    mut count_cb_gene_umi: FCount,
    mut quant_transcript: FQuant,
) -> Result<crate::generated::structs::SoloFeatureProcessRecordsResult, String>
where
    FCount: FnMut(&mut crate::generated::structs::SoloFeature) -> String,
    FQuant: FnMut(&mut crate::generated::structs::SoloFeature) -> String,
{
    let mut result = crate::generated::structs::SoloFeatureProcessRecordsResult::default();
    if p_solo.solo_type == SOLO_TYPE_NONE {
        return Ok(result);
    }

    let feature_names = [
        "SJ",
        "Transcript3p",
        "GeneFull",
        "GeneFull_ExonOverIntron",
        "GeneFull_Ex50pAS",
        "Gene",
        "VelocytoSimple",
        "Velocyto",
    ];
    let feature_name = if solo_feature.feature_type >= 0 {
        feature_names
            .get(solo_feature.feature_type as usize)
            .copied()
            .unwrap_or("")
    } else {
        ""
    };

    result.log_main.push_str(&format!(
        "{} ... Starting Solo post-map for {}\n",
        time_start, feature_name
    ));

    solo_feature.output_prefix = format!(
        "{}{}{}{}/",
        p.out_file_name_prefix,
        p_solo.out_file_names.first().cloned().unwrap_or_default(),
        feature_name,
        ""
    );
    solo_feature.output_prefix_filtered = format!("{}filtered/", solo_feature.output_prefix);
    result
        .created_directories
        .push(solo_feature.output_prefix.clone());

    if solo_feature.feature_type == SOLO_FEATURE_SJ && p.sj_all[0].is_empty() {
        p.sj_all[0].reserve(10_000_000);
        p.sj_all[1].reserve(10_000_000);
        for (start, gap) in sj_start_gap_rows {
            p.sj_all[0].push(*start);
            p.sj_all[1].push(*gap);
        }
        result.log_main.push_str(&format!(
            "Read splice junctions for Solo SJ feature: {}\n",
            p.sj_all[0].len()
        ));
    }

    solofeature_sumthreads_l8_solofeature_sumthreads(
        solo_feature,
        p,
        p_solo,
        read_bar_sum,
        read_feat_all,
        g_stats_all.read_n as u64,
    );

    if solo_feature.feature_type == SOLO_FEATURE_VELOCYTO {
        let gene_read_info = gene_solo_feature
            .map(|sf| sf.read_info.as_slice())
            .unwrap_or(&[]);
        result
            .log_main
            .push_str(&solofeature_countvelocyto_l12_solofeature_countvelocyto(
                solo_feature,
                gene_read_info,
                trans,
                p.run_thread_n,
                time_start,
                time_finished_counting,
                time_finished_collapsing,
                linux_proc_memory,
            ));
    } else if solo_feature.feature_type == SOLO_FEATURE_TRANSCRIPT3P {
        result.quant_transcript_called = true;
        result.log_main.push_str(&quant_transcript(solo_feature));
        result.returned_after_quant_transcript = true;
        return Ok(result);
    } else if p_solo.solo_type == SOLO_TYPE_SMART_SEQ {
        result
            .log_main
            .push_str(&solofeature_countsmartseq_l9_solofeature_countsmartseq(
                solo_feature,
                p,
                time_finished_redistribution,
                time_finished_collapsing,
                time_finished_counting,
            ));
    } else {
        result.count_cb_gene_umi_called = true;
        result.log_main.push_str(&count_cb_gene_umi(solo_feature));
    }

    let read_feat_sum = solo_feature
        .read_feat_sum
        .as_ref()
        .expect("SoloFeature::processRecords requires readFeatSum");
    result.files.insert(
        format!("{}Features.stats", solo_feature.output_prefix),
        soloreadfeature_l56_soloreadfeature_statsout(read_feat_sum),
    );

    result.log_main.push_str(&format!(
        "{} ... Solo: writing raw matrix\n",
        time_writing_raw_matrix
    ));
    let raw = solofeature_outputresults_l12_solofeature_outputresults(
        solo_feature,
        false,
        &format!("{}/raw/", solo_feature.output_prefix),
        p,
        p_solo,
        trans,
        current_dir,
    )?;
    result.created_directories.push(raw.created_directory);
    result.files.extend(raw.files);
    result.symlinks.extend(raw.symlinks);

    result.log_main.push_str(&format!(
        "{} ... Solo: cell filtering\n",
        time_cell_filtering
    ));
    let cell_filtering = solofeature_cellfiltering_l5_solofeature_cellfiltering(
        solo_feature,
        p_solo,
        gene_solo_feature,
        p,
        trans,
        current_dir,
    )?;
    if let Some(out) = &cell_filtering.output_results {
        result
            .created_directories
            .push(out.created_directory.clone());
        result.files.extend(out.files.clone());
        result.symlinks.extend(out.symlinks.clone());
    }
    result.log_main.push_str(&cell_filtering.log_main);
    result.cell_filtering = Some(cell_filtering);

    let stats_output = solofeature_statsoutput_l6_solofeature_statsoutput(
        solo_feature,
        p,
        p_solo,
        g_stats_all,
        ra_chunks,
    );
    result.files.extend(stats_output.files.clone());
    result.stats_output = Some(stats_output);

    solofeature_l29_solofeature_clearlarge(solo_feature);
    result.log_main.push_str("RAM after completing solo:\n");
    result.log_main.push_str(linux_proc_memory);
    Ok(result)
}

#[doc = "Original `blocksOverlap` at STAR/source/blocksOverlap.cpp:3. Args: t1: Transcript, t2: Transcript"]
pub fn blocksoverlap_l3_blocksoverlap(
    t1: &crate::generated::structs::Transcript,
    t2: &crate::generated::structs::Transcript,
) -> u32 {
    let mut i1 = 0usize;
    let mut i2 = 0usize;
    let mut n_overlap = 0;
    while i1 < t1.n_exons as usize && i2 < t2.n_exons as usize {
        let rs1 = t1.exons[i1][EX_R];
        let rs2 = t2.exons[i2][EX_R];
        let re1 = t1.exons[i1][EX_R] + t1.exons[i1][EX_L];
        let re2 = t2.exons[i2][EX_R] + t2.exons[i2][EX_L];
        let gs1 = t1.exons[i1][EX_G];
        let gs2 = t2.exons[i2][EX_G];

        if rs1 >= re2 {
            i2 += 1;
        } else if rs2 >= re1 {
            i1 += 1;
        } else if gs1.wrapping_sub(rs1) != gs2.wrapping_sub(rs2) {
            if re1 >= re2 {
                i2 += 1;
            }
            if re2 >= re1 {
                i1 += 1;
            }
        } else {
            n_overlap += re1.min(re2) - rs1.max(rs2);
            if re1 >= re2 {
                i2 += 1;
            }
            if re2 >= re1 {
                i1 += 1;
            }
        }
    }
    n_overlap
}

#[doc = "Original `SoloReadFeature::record` at STAR/source/SoloReadFeature_record.cpp:20. Args: soloBar: SoloReadBarcode, nTr: uint, alignOut: Transcript, iRead: uint64, readAnnot: ReadAnnotations"]
pub fn soloreadfeature_record_l20_soloreadfeature_record(
    rf: &mut crate::generated::structs::SoloReadFeature,
    p: &crate::generated::structs::Parameters,
    solo_bar: &mut crate::generated::structs::SoloReadBarcode,
    n_tr: u32,
    align_out: &[crate::generated::structs::Transcript],
    i_read: u64,
    read_annot: &crate::generated::structs::ReadAnnotations,
) {
    if p.p_solo.solo_type == 0 {
        return;
    }

    if rf.stats.v.len() < SOLO_READ_FEATURE_N_STATS {
        rf.stats.v.resize(SOLO_READ_FEATURE_N_STATS, 0);
    }

    let feature_index = rf.feature_type as usize;
    let ann_feature_default = crate::generated::structs::ReadAnnotFeature::default();
    let ann_feature = read_annot
        .annot_features
        .get(feature_index)
        .unwrap_or(&ann_feature_default);
    let read_stats_yes = p
        .p_solo
        .read_stats_yes
        .get(feature_index)
        .copied()
        .unwrap_or(false);

    if read_stats_yes {
        if n_tr == 1 {
            rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_GENOME_U;
        } else if n_tr > 1 {
            rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_GENOME_M;
        }

        for tr in align_out.iter().take(n_tr as usize) {
            if p.p_ge.chr_set_mito.contains(&(tr.chr as u64)) {
                rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_MITO;
            }
        }

        match ann_feature.ov_type {
            1 | 3 => rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_EXONIC,
            5 => rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_INTRONIC,
            2 | 4 => rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_EXONIC_AS,
            6 => rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_INTRONIC_AS,
            _ => {}
        }

        if solo_bar.cb_match < 0 && p.p_solo.cb_wl_yes {
            if ann_feature.f_set.len() == 1 {
                rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_FEATURE_U;
            } else if ann_feature.f_set.len() > 1 {
                rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_FEATURE_M;
            }
            rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_CB_MATCH;
            for ibit in 0..SOLO_READ_FLAG_N_BITS {
                rf.read_flag.flag_counts_no_cb[ibit] +=
                    ((rf.read_flag.flag >> ibit) & 1_u32) as u64;
            }
        }
    }

    if solo_bar.cb_match < 0 {
        return;
    }

    let mut re_fe = crate::generated::structs::ReadSoloFeatures {
        align_out: align_out.to_vec(),
        ..Default::default()
    };

    let mut n_feat = 0_u32;
    if n_tr == 0 {
        rf.stats.v[SOLO_READ_FEATURE_STAT_NO_UNMAPPED] += 1;
    } else {
        match rf.feature_type {
            SOLO_FEATURE_GENE
            | SOLO_FEATURE_GENE_FULL
            | SOLO_FEATURE_GENE_FULL_EX50P_AS
            | SOLO_FEATURE_GENE_FULL_EXON_OVER_INTRON => {
                if solo_bar.solo_type == 4 {
                    for itr in (0..n_tr as usize).rev() {
                        if ann_feature
                            .f_align
                            .get(itr)
                            .map(|genes| !genes.is_empty())
                            .unwrap_or(false)
                        {
                            re_fe.ind_annot_tr = itr;
                            break;
                        }
                    }
                }

                if ann_feature.f_set.is_empty() {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_NO_NO_FEATURE] += 1;
                } else if ann_feature.f_set.len() > 1 {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_MULTI_FEATURE] += 1;
                    rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_FEATURE_M;
                    if n_tr > 1 {
                        rf.stats.v[SOLO_READ_FEATURE_STAT_SUB_MULTI_FEATURE_MULTI_GENOMIC] += 1;
                    }
                    if p.p_solo.multi_map.yes_multi {
                        re_fe.gene_mult.reserve(ann_feature.f_set.len());
                        for g in &ann_feature.f_set {
                            re_fe.gene_mult.push(*g | (1_u32 << 31));
                        }
                        n_feat = soloreadfeature_record_l206_outputreadcb(
                            &mut rf.stream_reads,
                            i_read,
                            rf.feature_type,
                            solo_bar,
                            &re_fe,
                            read_annot,
                            &rf.read_flag,
                        );
                    }
                } else {
                    re_fe.gene = *ann_feature.f_set.iter().next().unwrap();
                    rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_FEATURE_U;
                    let out_i_read = if rf.read_index_yes { i_read } else { u64::MAX };
                    n_feat = soloreadfeature_record_l206_outputreadcb(
                        &mut rf.stream_reads,
                        out_i_read,
                        rf.feature_type,
                        solo_bar,
                        &re_fe,
                        read_annot,
                        &rf.read_flag,
                    );
                }
            }
            SOLO_FEATURE_SJ => {
                if n_tr > 1 {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_SUB_MULTI_FEATURE_MULTI_GENOMIC] += 1;
                    rf.stats.v[SOLO_READ_FEATURE_STAT_MULTI_FEATURE] += 1;
                } else if let Some(tr) = align_out.first() {
                    transcript_l38_transcript_extractsplicejunctions(
                        tr,
                        &mut re_fe.sj,
                        &mut re_fe.sj_annot,
                    );
                    if re_fe.sj.is_empty() {
                        rf.stats.v[SOLO_READ_FEATURE_STAT_NO_NO_FEATURE] += 1;
                    } else {
                        rf.read_flag.flag |= 1_u32 << SOLO_READ_FLAG_FEATURE_U;
                        let out_i_read = if rf.read_index_yes { i_read } else { u64::MAX };
                        n_feat = soloreadfeature_record_l206_outputreadcb(
                            &mut rf.stream_reads,
                            out_i_read,
                            rf.feature_type,
                            solo_bar,
                            &re_fe,
                            read_annot,
                            &rf.read_flag,
                        );
                    }
                }
            }
            SOLO_FEATURE_TRANSCRIPT3P => {
                if read_annot.transcript_concordant.is_empty() || solo_bar.cb_match > 1 {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_NO_NO_FEATURE] += 1;
                } else {
                    n_feat = soloreadfeature_record_l206_outputreadcb(
                        &mut rf.stream_reads,
                        i_read,
                        rf.feature_type,
                        solo_bar,
                        &re_fe,
                        read_annot,
                        &rf.read_flag,
                    );
                }
                if read_annot.transcript_concordant.len() == 1 {
                    let dist = read_annot.transcript_concordant[0][1] as usize;
                    if dist < rf.transcript_dist_count.len() {
                        rf.transcript_dist_count[dist] += 1;
                    }
                }
            }
            SOLO_FEATURE_VELOCYTO => {
                if read_annot.tr_velocyto_type.is_empty() {
                    rf.stats.v[SOLO_READ_FEATURE_STAT_NO_NO_FEATURE] += 1;
                } else {
                    let mut tr_velocyto_type = read_annot.tr_velocyto_type.clone();
                    tr_velocyto_type.sort_by_key(|tt| tt.tr);
                    rf.stream_reads
                        .push_str(&format!("{} {}", i_read, tr_velocyto_type.len()));
                    for tt in &tr_velocyto_type {
                        rf.stream_reads
                            .push_str(&format!(" {} {}", tt.tr, tt.type_ as u32));
                    }
                    rf.stream_reads.push('\n');
                    n_feat = 1;
                }
            }
            _ => {}
        }
    }

    if n_feat == 0 && (rf.read_info_yes || read_stats_yes) {
        soloreadfeature_record_l206_outputreadcb(
            &mut rf.stream_reads,
            i_read,
            -1,
            solo_bar,
            &re_fe,
            read_annot,
            &rf.read_flag,
        );
    }

    if n_feat == 0 {
        return;
    }

    if p.p_solo.cb_wl_yes {
        for cbi in &solo_bar.cb_match_ind {
            let cbi = *cbi as usize;
            if cbi >= rf.cb_read_count.len() {
                rf.cb_read_count.resize(cbi + 1, 0);
            }
            rf.cb_read_count[cbi] += n_feat;
        }
    } else if let Some(cbi) = solo_bar.cb_match_ind.first() {
        *rf.cb_read_count_map.entry(*cbi).or_insert(0) += n_feat;
    }
}

#[doc = "Original `outputReadCB` at STAR/source/SoloReadFeature_record.cpp:206. Args: streamOut: fstream, iRead: uint64, featureType: int32, soloBar: SoloReadBarcode, reFe: ReadSoloFeatures, readAnnot: ReadAnnotations, readFlag: SoloReadFlagClass"]
pub fn soloreadfeature_record_l206_outputreadcb(
    stream_out: &mut String,
    i_read: u64,
    feature_type: i32,
    solo_bar: &mut crate::generated::structs::SoloReadBarcode,
    re_fe: &crate::generated::structs::ReadSoloFeatures,
    read_annot: &crate::generated::structs::ReadAnnotations,
    read_flag: &crate::generated::structs::SoloReadFlagClass,
) -> u32 {
    if solo_bar.solo_type == 4 && feature_type != -1 {
        solo_bar.umi_b =
            transcript_l53_transcript_chrstartlengthextended(&re_fe.align_out[re_fe.ind_annot_tr]);
    }

    let mut nout = 1_u32;

    match feature_type {
        -1 => {
            stream_out.push_str(&format!(
                "{} {} {} -1 {} {}\n",
                solo_bar.umi_b, i_read, read_flag.flag, solo_bar.cb_match, solo_bar.cb_match_string
            ));
        }
        SOLO_FEATURE_GENE
        | SOLO_FEATURE_GENE_FULL
        | SOLO_FEATURE_GENE_FULL_EX50P_AS
        | SOLO_FEATURE_GENE_FULL_EXON_OVER_INTRON => {
            if re_fe.gene_mult.is_empty() {
                stream_out.push_str(&format!("{} ", solo_bar.umi_b));
                if i_read != u64::MAX {
                    stream_out.push_str(&format!("{} {} ", i_read, read_flag.flag));
                }
                stream_out.push_str(&format!(
                    "{} {} {}\n",
                    re_fe.gene, solo_bar.cb_match, solo_bar.cb_match_string
                ));
            } else {
                for g in &re_fe.gene_mult {
                    stream_out.push_str(&format!(
                        "{} {} {} {} {} {}\n",
                        solo_bar.umi_b,
                        i_read,
                        read_flag.flag,
                        g,
                        solo_bar.cb_match,
                        solo_bar.cb_match_string
                    ));
                }
                nout = re_fe.gene_mult.len() as u32;
            }
        }
        SOLO_FEATURE_SJ => {
            for sj in &re_fe.sj {
                stream_out.push_str(&format!("{} ", solo_bar.umi_b));
                if i_read != u64::MAX {
                    stream_out.push_str(&format!("{} {} ", i_read, read_flag.flag));
                }
                stream_out.push_str(&format!(
                    "{} {} {} {}\n",
                    sj[0], sj[1], solo_bar.cb_match, solo_bar.cb_match_string
                ));
            }
            nout = re_fe.sj.len() as u32;
        }
        SOLO_FEATURE_TRANSCRIPT3P => {
            stream_out.push_str(&format!(
                "{} {} {}",
                solo_bar.cb_match_string,
                solo_bar.umi_b,
                read_annot.transcript_concordant.len()
            ));
            for tt in &read_annot.transcript_concordant {
                stream_out.push_str(&format!(" {} {}", tt[0], tt[1]));
            }
            if i_read != u64::MAX {
                stream_out.push_str(&format!(" {}", i_read));
            }
            stream_out.push('\n');
            nout = 1;
        }
        _ => {}
    }

    nout
}

#[doc = "Original `bam_cigarString` at STAR/source/BAMfunctions.cpp:5. Args: b: bam1_t"]
pub fn bamfunctions_l5_bam_cigarstring(cigar: &[u32], n_cigar: i32) -> String {
    let mut cigar_string = String::new();
    if n_cigar > 0 {
        for i in 0..n_cigar as usize {
            cigar_string.push_str(&(cigar[i] >> 4).to_string());
            cigar_string.push(match cigar[i] & 0xf {
                0 => 'M',
                1 => 'I',
                2 => 'D',
                3 => 'N',
                4 => 'S',
                5 => 'H',
                6 => 'P',
                7 => '=',
                8 => 'X',
                9 => 'B',
                _ => '?',
            });
        }
    }
    cigar_string
}

#[doc = "Original `bam_read1_fromArray` at STAR/source/BAMfunctions.cpp:30. Args: bamChar: char, b: bam1_t"]
pub fn bamfunctions_l30_bam_read1_fromarray(
    bam_char: &[u8],
    b: &mut crate::generated::structs::Bam1,
) -> i32 {
    if bam_char.len() < 36 {
        return -4;
    }
    let block_len = i32::from_ne_bytes(bam_char[0..4].try_into().unwrap());
    let mut x = [0u32; 8];
    for ii in 0..8 {
        let start = 4 + ii * 4;
        x[ii] = u32::from_ne_bytes(bam_char[start..start + 4].try_into().unwrap());
    }

    b.core.tid = x[0] as i32;
    b.core.pos = x[1] as i32;
    b.core.bin = x[2] >> 16;
    b.core.qual = (x[2] >> 8) & 0xff;
    b.core.l_qname = x[2] & 0xff;
    b.core.flag = x[3] >> 16;
    b.core.n_cigar = x[3] & 0xffff;
    b.core.l_qseq = x[4] as i32;
    b.core.mtid = x[5] as i32;
    b.core.mpos = x[6] as i32;
    b.core.isize = x[7] as i32;
    b.l_data = block_len - 32;
    if b.l_data < 0 || b.core.l_qseq < 0 {
        return -4;
    }

    if b.m_data < b.l_data {
        b.m_data = b.l_data;
        if b.m_data > 0 {
            b.m_data = (b.m_data as u32).next_power_of_two() as i32;
        }
    }
    b.data_offset = 4 * 9;

    4 + block_len
}

#[doc = "Original `outBAMwriteHeader` at STAR/source/BAMfunctions.cpp:77. Args: fp: BGZF, samh: string, chrn: vector <string>, chrl: vector <uint>"]
pub fn bamfunctions_l77_outbamwriteheader(samh: &str, chrn: &[String], chrl: &[u32]) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"BAM\x01");
    let hlen = samh.len() as i32;
    out.extend_from_slice(&hlen.to_ne_bytes());
    out.extend_from_slice(samh.as_bytes());
    let nchr = chrn.len() as i32;
    out.extend_from_slice(&nchr.to_ne_bytes());
    for ii in 0..chrn.len() {
        let rlen = chrn[ii].len() as i32 + 1;
        let slen = chrl[ii] as i32;
        out.extend_from_slice(&rlen.to_ne_bytes());
        out.extend_from_slice(chrn[ii].as_bytes());
        out.push(0);
        out.extend_from_slice(&slen.to_ne_bytes());
    }
    out
}

#[doc = "Original `reg2bin` at STAR/source/BAMfunctions.cpp:95. Args: beg: int, end: int"]
pub fn bamfunctions_l95_reg2bin(beg: i32, mut end: i32) -> i32 {
    end -= 1;
    if beg >> 14 == end >> 14 {
        return ((1 << 15) - 1) / 7 + (beg >> 14);
    }
    if beg >> 17 == end >> 17 {
        return ((1 << 12) - 1) / 7 + (beg >> 17);
    }
    if beg >> 20 == end >> 20 {
        return ((1 << 9) - 1) / 7 + (beg >> 20);
    }
    if beg >> 23 == end >> 23 {
        return ((1 << 6) - 1) / 7 + (beg >> 23);
    }
    if beg >> 26 == end >> 26 {
        return 1 + (beg >> 26);
    }
    0
}

#[doc = "Original `bamAttrArrayWrite` at STAR/source/BAMfunctions.cpp:106. Args: attr: int32, tagName: char, attrArray: char"]
pub fn bamfunctions_l106_bamattrarraywrite(
    attr: i32,
    tag_name: &[u8],
    attr_array: &mut [u8],
) -> i32 {
    attr_array[0] = tag_name[0];
    attr_array[1] = tag_name[1];
    attr_array[2] = b'i';
    attr_array[3..7].copy_from_slice(&attr.to_ne_bytes());
    7
}

