#[doc = "Original `ReadAlign::alignedAnnotation` at STAR/source/ReadAlign_outputAlignments.cpp:298. Args: "]
pub fn readalign_outputalignments_l298_readalign_alignedannotation(
    transcriptome: &mut crate::generated::structs::Transcriptome,
    p: &crate::generated::structs::Parameters,
    n_tr: u64,
    tr_mult: &[crate::generated::structs::Transcript],
    aligns_gen_out: &crate::generated::structs::ReadAlignGenomeTransformResult,
    read_annot: &mut crate::generated::structs::ReadAnnotations,
) {
    let min_features = (SOLO_FEATURE_VELOCYTO as usize) + 1;
    if read_annot.annot_features.len() < min_features {
        read_annot
            .annot_features
            .resize(min_features, Default::default());
    }

    if p.quant_ge_count_yes {
        if p.p_ge.transform.out_quant {
            transcriptome_genecountsaddalign_l4_transcriptome_genecountsaddalign(
                transcriptome,
                aligns_gen_out.al_n,
                &aligns_gen_out.al_mult,
                &mut read_annot.gene_exon_overlap,
            );
        } else {
            transcriptome_genecountsaddalign_l4_transcriptome_genecountsaddalign(
                transcriptome,
                n_tr as u32,
                tr_mult,
                &mut read_annot.gene_exon_overlap,
            );
        }
    }

    if p.quant_gene_full_yes {
        transcriptome_genefullalignoverlap_l5_transcriptome_genefullalignoverlap(
            transcriptome,
            n_tr as u32,
            tr_mult,
            p.p_solo.strand,
            &mut read_annot.annot_features[SOLO_FEATURE_GENE_FULL as usize],
        );
    }

    if p.quant_gene_yes {
        transcriptome_classifyalign_l177_transcriptome_classifyalign(
            transcriptome,
            &p.p_solo,
            tr_mult,
            read_annot,
        );
    }

    if p.quant_gene_full_exon_over_intron_yes {
        let gene_concordant = read_annot.annot_features[SOLO_FEATURE_GENE as usize].clone();
        transcriptome_genefullalignoverlap_exonoverintron_l5_transcriptome_genefullalignoverlap_exonoverintron(
            transcriptome,
            n_tr as u32,
            tr_mult,
            p.p_solo.strand,
            &mut read_annot.annot_features[SOLO_FEATURE_GENE_FULL_EXON_OVER_INTRON as usize],
            &gene_concordant,
        );
    }

    if p.quant_gene_full_ex50p_as_yes {
        transcriptome_alignexonoverlap_l10_transcriptome_alignexonoverlap(
            transcriptome,
            n_tr as u32,
            tr_mult,
            p.p_solo.strand,
            &mut read_annot.annot_features[SOLO_FEATURE_GENE_FULL_EX50P_AS as usize],
        );
    }
}

#[doc = "Original `ReadAlign::stitchPieces` at STAR/source/ReadAlign_stitchPieces.cpp:12. Args: R: char, Lread: uint"]
pub fn readalign_stitchpieces_l12_readalign_stitchpieces(
    read_align: &mut crate::generated::structs::ReadAlign,
    r: &[Vec<u8>],
    l_read: u32,
    map_gen: &crate::generated::structs::Genome,
    p: &crate::generated::structs::Parameters,
) -> Result<(), String> {
    let win_bin_n = p.win_bin_n as usize;
    if read_align.win_bin[0].len() < win_bin_n {
        read_align.win_bin[0].resize(win_bin_n, UINT_WIN_BIN_MAX);
    }
    if read_align.win_bin[1].len() < win_bin_n {
        read_align.win_bin[1].resize(win_bin_n, UINT_WIN_BIN_MAX);
    }
    read_align.win_bin[0][..win_bin_n].fill(UINT_WIN_BIN_MAX);
    read_align.win_bin[1][..win_bin_n].fill(UINT_WIN_BIN_MAX);

    let align_windows = p.align_windows_per_read_nmax as usize;
    let seed_per_window = p.seed_per_window_nmax as usize;
    if read_align.wc.len() < align_windows {
        read_align.wc.resize(align_windows, [0; WC_SIZE]);
    }
    if read_align.n_wa.len() < align_windows {
        read_align.n_wa.resize(align_windows, 0);
    }
    if read_align.n_wap.len() < align_windows {
        read_align.n_wap.resize(align_windows, 0);
    }
    if read_align.wal_rec.len() < align_windows {
        read_align.wal_rec.resize(align_windows, 0);
    }
    if read_align.w_last_anchor.len() < align_windows {
        read_align.w_last_anchor.resize(align_windows, 0);
    }
    if read_align.wa.len() < align_windows {
        read_align.wa.resize(align_windows, Vec::new());
    }
    for i_w in 0..align_windows {
        if read_align.wa[i_w].len() < seed_per_window {
            read_align.wa[i_w].resize(seed_per_window, [0; WA_SIZE]);
        }
    }
    if read_align.wa_incl.len() < seed_per_window {
        read_align.wa_incl.resize(seed_per_window, false);
    }
    if read_align.tr_all.len() < align_windows {
        read_align.tr_all.resize(align_windows, Vec::new());
    }
    if read_align.n_win_tr.len() < align_windows {
        read_align.n_win_tr.resize(align_windows, 0);
    }

    read_align.n_w = 0;
    for i_p in 0..read_align.n_p as usize {
        if read_align.pc[i_p][PC_NREP] <= p.win_anchor_multimap_nmax {
            let a_dir = read_align.pc[i_p][PC_DIR];
            let a_length = read_align.pc[i_p][PC_LENGTH];

            for i_sa in read_align.pc[i_p][PC_SASTART]..=read_align.pc[i_p][PC_SAEND] {
                let mut a1 = map_gen.sa[i_sa as usize] as u64;
                let mut a_str = (a1 >> map_gen.gstrand_bit) as u32;
                a1 &= map_gen.gstrand_mask as u64;

                if a_dir == 1 && a_str == 0 {
                    a_str = 1;
                } else if a_dir == 0 && a_str == 1 {
                    a1 = map_gen.n_genome - (a_length as u64 + a1);
                } else if a_dir == 1 && a_str == 1 {
                    a_str = 0;
                    a1 = map_gen.n_genome - (a_length as u64 + a1);
                }

                if read_align.revert_strand {
                    a_str = 1 - a_str;
                }

                if a1 >= map_gen.sj_gstart {
                    let mut a1_d = 0;
                    let mut a_length_d = 0;
                    let mut a1_a = 0;
                    let mut a_length_a = 0;
                    let mut sj1 = 0;
                    if sjalignsplit_l3_sjalignsplit(
                        a1,
                        a_length as u64,
                        map_gen,
                        &mut a1_d,
                        &mut a_length_d,
                        &mut a1_a,
                        &mut a_length_a,
                        &mut sj1,
                    ) {
                        let add_status =
                            readalign_createextendwindowswithalign_l7_readalign_createextendwindowswithalign(
                                read_align,
                                map_gen,
                                p,
                                a1_d as u32,
                                a_str,
                            );
                        if add_status == EXIT_CREATE_EXTEND_WINDOWS_WITH_ALIGN_TOO_MANY_WINDOWS {
                            break;
                        }
                        let add_status =
                            readalign_createextendwindowswithalign_l7_readalign_createextendwindowswithalign(
                                read_align,
                                map_gen,
                                p,
                                a1_a as u32,
                                a_str,
                            );
                        if add_status == EXIT_CREATE_EXTEND_WINDOWS_WITH_ALIGN_TOO_MANY_WINDOWS {
                            break;
                        }
                    }
                } else {
                    let add_status =
                        readalign_createextendwindowswithalign_l7_readalign_createextendwindowswithalign(
                            read_align,
                            map_gen,
                            p,
                            a1 as u32,
                            a_str,
                        );
                    if add_status == EXIT_CREATE_EXTEND_WINDOWS_WITH_ALIGN_TOO_MANY_WINDOWS {
                        break;
                    }
                }
            }
        }
    }

    for i_win in 0..read_align.n_w as usize {
        if read_align.wc[i_win][WC_G_START] <= read_align.wc[i_win][WC_G_END] {
            let mut wb = read_align.wc[i_win][WC_G_START];
            let mut ii = 0;
            while ii < p.win_flank_nbins
                && wb > 0
                && map_gen.chr_bin[((wb - 1) >> p.win_bin_chr_nbits) as usize]
                    == read_align.wc[i_win][WC_CHR]
            {
                wb -= 1;
                read_align.win_bin[read_align.wc[i_win][WC_STR] as usize][wb as usize] =
                    i_win as u32;
                ii += 1;
            }
            read_align.wc[i_win][WC_G_START] = wb;

            wb = read_align.wc[i_win][WC_G_END];
            ii = 0;
            while ii < p.win_flank_nbins
                && wb + 1 < p.win_bin_n
                && map_gen.chr_bin[((wb + 1) >> p.win_bin_chr_nbits) as usize]
                    == read_align.wc[i_win][WC_CHR]
            {
                wb += 1;
                read_align.win_bin[read_align.wc[i_win][WC_STR] as usize][wb as usize] =
                    i_win as u32;
                ii += 1;
            }
            read_align.wc[i_win][WC_G_END] = wb;
        }
        read_align.n_wa[i_win] = 0;
        read_align.wal_rec[i_win] = 0;
        read_align.w_last_anchor[i_win] = u32::MAX;
    }

    read_align.n_wall = read_align.n_w;

    for i_p in 0..read_align.n_p as usize {
        let a_nrep = read_align.pc[i_p][PC_NREP];
        let a_frag = read_align.pc[i_p][PC_IFRAG];
        let a_length = read_align.pc[i_p][PC_LENGTH];
        let a_dir = read_align.pc[i_p][PC_DIR];
        let a_anchor = a_nrep <= p.win_anchor_multimap_nmax;

        for ii in 0..read_align.n_w as usize {
            read_align.n_wap[ii] = 0;
        }

        for i_sa in read_align.pc[i_p][PC_SASTART]..=read_align.pc[i_p][PC_SAEND] {
            let mut a1 = map_gen.sa[i_sa as usize] as u64;
            let mut a_str = (a1 >> map_gen.gstrand_bit) as u32;
            a1 &= map_gen.gstrand_mask as u64;
            let mut a_rstart = read_align.pc[i_p][PC_R_START];

            if a_dir == 1 && a_str == 0 {
                a_str = 1;
                a_rstart = l_read - (a_length + a_rstart);
            } else if a_dir == 0 && a_str == 1 {
                a_rstart = l_read - (a_length + a_rstart);
                a1 = map_gen.n_genome - (a_length as u64 + a1);
            } else if a_dir == 1 && a_str == 1 {
                a_str = 0;
                a1 = map_gen.n_genome - (a_length as u64 + a1);
            }

            if read_align.revert_strand {
                a_str = 1 - a_str;
            }

            if a1 >= map_gen.sj_gstart {
                let mut a1_d = 0;
                let mut a_length_d = 0;
                let mut a1_a = 0;
                let mut a_length_a = 0;
                let mut isj1 = 0;
                if sjalignsplit_l3_sjalignsplit(
                    a1,
                    a_length as u64,
                    map_gen,
                    &mut a1_d,
                    &mut a_length_d,
                    &mut a1_a,
                    &mut a_length_a,
                    &mut isj1,
                ) {
                    readalign_assignaligntowindow_l6_readalign_assignaligntowindow(
                        read_align,
                        a1_d as u32,
                        a_length_d as u32,
                        a_str,
                        a_nrep,
                        a_frag,
                        a_rstart,
                        a_anchor,
                        isj1 as u32,
                        p.win_bin_nbits,
                        p.seed_per_window_nmax,
                    )?;
                    readalign_assignaligntowindow_l6_readalign_assignaligntowindow(
                        read_align,
                        a1_a as u32,
                        a_length_a as u32,
                        a_str,
                        a_nrep,
                        a_frag,
                        a_rstart + a_length_d as u32,
                        a_anchor,
                        isj1 as u32,
                        p.win_bin_nbits,
                        p.seed_per_window_nmax,
                    )?;
                } else {
                    continue;
                }
            } else {
                readalign_assignaligntowindow_l6_readalign_assignaligntowindow(
                    read_align,
                    a1 as u32,
                    a_length,
                    a_str,
                    a_nrep,
                    a_frag,
                    a_rstart,
                    a_anchor,
                    u32::MAX,
                    p.win_bin_nbits,
                    p.seed_per_window_nmax,
                )?;
            }
        }
    }

    read_align.tr_best = (*read_align.tr_init).clone();
    let mut i_w1 = 0usize;
    let mut tr_n_total = 0u32;

    for i_w in 0..read_align.n_w as usize {
        if read_align.n_wa[i_w] == 0 {
            continue;
        }

        if read_align.w_last_anchor[i_w] < read_align.n_wa[i_w] {
            let last_anchor = read_align.w_last_anchor[i_w] as usize;
            read_align.wa[i_w][last_anchor][WA_ANCHOR] = 2;
        }

        for ii in 0..read_align.n_wa[i_w] as usize {
            read_align.wa_incl[ii] = false;
        }

        let mut tr_a = (*read_align.tr_init).clone();
        tr_a.chr = read_align.wc[i_w][WC_CHR];
        tr_a.str_ = read_align.wc[i_w][WC_STR];
        tr_a.ro_str = if read_align.revert_strand {
            1 - tr_a.str_
        } else {
            tr_a.str_
        };
        tr_a.max_score = 0;

        if tr_n_total + p.align_transcripts_per_window_nmax >= p.align_transcripts_per_read_nmax {
            break;
        }

        let mut w_tr = Vec::new();
        w_tr.push(tr_a.clone());
        let mut n_win_tr = 0u32;
        let read_index = if tr_a.ro_str == 0 { 0 } else { 2 };
        let read_bases: &[u8] = if read_index < r.len() {
            &r[read_index]
        } else if tr_a.ro_str as usize % 2 < r.len() {
            &r[tr_a.ro_str as usize % 2]
        } else {
            &[]
        };
        let wa_row = read_align.wa[i_w].clone();
        let mut wa_incl = read_align.wa_incl.clone();
        stitchwindowaligns_l8_stitchwindowaligns(
            0,
            read_align.n_wa[i_w],
            0,
            &mut wa_incl,
            0,
            0,
            tr_a,
            l_read,
            &wa_row,
            read_bases,
            map_gen,
            p,
            &mut w_tr,
            &mut n_win_tr,
            read_align,
        )?;
        read_align.wa_incl = wa_incl;

        if n_win_tr == 0 {
            continue;
        }

        if w_tr[0].max_score > read_align.tr_best.max_score
            || (w_tr[0].max_score == read_align.tr_best.max_score
                && w_tr[0].g_length < read_align.tr_best.g_length)
        {
            read_align.tr_best = w_tr[0].clone();
        }

        if read_align.tr_all.len() <= i_w1 {
            read_align.tr_all.resize(i_w1 + 1, Vec::new());
        }
        read_align.tr_all[i_w1] = w_tr;
        if read_align.n_win_tr.len() <= i_w1 {
            read_align.n_win_tr.resize(i_w1 + 1, 0);
        }
        read_align.n_win_tr[i_w1] = n_win_tr as u64;
        tr_n_total += n_win_tr;
        i_w1 += 1;
    }

    read_align.n_w = i_w1 as u32;
    read_align.n_tr = tr_n_total as u64;

    if read_align.tr_best.max_score == 0 {
        read_align.map_marker = MARKER_NO_GOOD_WINDOW;
        read_align.n_w = 0;
    }

    Ok(())
}

#[doc = "Original `exitWithError` at STAR/source/ErrorWarning.cpp:8. Args: messageOut: string, streamOut1: ostream, streamOut2: ostream, errorInt: int, P: Parameters"]
