        *a_length_d = map_gen.sjdb_overhang as u64 - sj1;
        *a_length_a = a_length - *a_length_d;
        *a1_d = map_gen.sj_dstart[*isj as usize] + sj1;
        *a1_a = map_gen.sj_astart[*isj as usize];
